\label{IAproto}
Let $X$ be a compact Hausdorff space.  A \emph{(proto) implicit atlas} of dimension $d$ on $X$ is an index set $A$ along with the following data:
\begin{rlist}
\item(Obstruction spaces) A finite-dimensional $\mathbb R$ vector space $E_\alpha$ for all $\alpha\in A$ (let $E_I:=\bigoplus_{\alpha\in I}E_\alpha$).
\item(Thickenings) A Hausdorff space $X_I$ for all finite $I\subseteq A$, and a homeomorphism $X\to X_\varnothing$.
\item(Kuranishi maps) A function $s_\alpha:X_I\to E_\alpha$ for all $\alpha\in I\subseteq A$ (for $I\subseteq J$, let $s_I:X_J\to E_I$ denote $\bigoplus_{\alpha\in I}s_\alpha$).
\item(Footprints) An open set $U_{IJ}\subseteq X_I$ for all $I\subseteq J\subseteq A$.
\item(Footprint maps) A function $\psi_{IJ}:(s_{J\setminus I}|X_J)^{-1}(0)\to U_{IJ}$ for all $I\subseteq J\subseteq A$.
\end{rlist}
which must satisfy the following ``compatibility axioms'':
\begin{rlist}
\item$\psi_{IJ}\psi_{JK}=\psi_{IK}$ and $\psi_{II}=\operatorname{id}$.
\item$s_I\psi_{IJ}=s_I$.
\item$U_{IJ_1}\cap U_{IJ_2}=U_{I,J_1\cup J_2}$ and $U_{II}=X_I$.
\item$\psi_{IJ}^{-1}(U_{IK})=U_{JK}\cap(s_{J\setminus I}|X_J)^{-1}(0)$.
\item(Homeomorphism axiom) $\psi_{IJ}$ is a homeomorphism.
\setcounter{rcountsave}{\value{rcounti}}
\end{rlist}
and the following ``transversality axioms'':
\begin{rlist}
\setcounter{rcounti}{\value{rcountsave}}
\item(Submersion axiom) $s_{J\setminus I}:X_J\to E_{J\setminus I}$ is locally modeled on the projection $\mathbb R^{d+\dim E_J}\to\mathbb R^{\dim E_{J\setminus I}}$ over $0\in E_{J\setminus I}$ for $\#I\geq 1$ (in particular, taking $I=J$ implies that $X_I$ is a topological manifold dimension $d+\dim E_I$ for $\#I\geq 1$).
\item(Covering axiom) $X_\varnothing=\bigcup_{\varnothing\ne I\subseteq A}\psi_{\varnothing I}((s_I|X_I)^{-1}(0))$.
\end{rlist}

define the orbifold fiber product by the following universal property:
\begin{equation}
\operatorname{Hom}(S,\mathcal X\times_\mathcal Z\mathcal Y):=\operatorname{Hom}(S,\mathcal X)\times_{\operatorname{Hom}(S,\mathcal Z)}\operatorname{Hom}(S,\mathcal Y)
\end{equation}
for any smooth manifold $S$.

We define $A$ to be the set of all \emph{thickening datums} where a thickening datum is a $4$-tuple $(r_\alpha,D_\alpha,E_\alpha,\lambda_\alpha)$ consisting of:
\begin{rlist}
\item An integer $r_\alpha>2$; let $\Gamma_\alpha:=S_{r_\alpha}$.

(X,B)_I$ (any finite $I\subseteq A$) is defined as the set of:
\begin{rlist}
\item\label{firstcondition}A smooth map $u:C\to X$ where $C$ is a nodal curve of genus $0$ so that for all $\alpha\in I$, we have $u\pitchfork D_\alpha$ (meaning $u^{-1}(\partial D_\alpha)=\varnothing$ and for all $p\in u^{-1}(D_\alpha)$, the differential $(du)_p:T_pC\to T_{u(p)}X/T_{u(p)}D_\alpha$ is surjective and $p$ is not a node of $C$) with $\#u^{-1}(D_\alpha)=r_\alpha$ such that adding these $r_\alpha$ intersections as marked points makes $C$ stable.

\label{smoothIAdef}
A \emph{smooth structure} on an implicit atlas consists of a smooth structure on each $X_I^\mathrm{reg}$ such that:
\begin{rlist}
\item$\Gamma_I$ acts smoothly on $X_I^\mathrm{reg}$.
\item$s_I$ is smooth over $X_I^\mathrm{reg}$.
\item$s_{J\setminus I}:X_J\to E_{J\setminus I}$ is a smooth submersion over $\psi_{IJ}^{-1}(X_I^\mathrm{reg})$.
\item$\psi_{IJ}$ is a local diffeomorphism over $\psi_{IJ}^{-1}(X_I^\mathrm{reg})$.
\end{rlist}

Let $X$ be a space with finite implicit atlas $A$ with boundary.  For $I\subseteq J\subseteq A$, we define:
\begin{equation*}
X_{I,J,A}:=\left\{(e,t,x)\in E_A\times\mathbb R_{\geq 0}^A\times X_J^\mathrm{reg}\;\middle|\;\begin{matrix}t_\alpha=0\text{ for }\alpha\in A\setminus I\hfill\cr s_\alpha(x)=t_\alpha e_\alpha\text{ for }\alpha\in J\hfill\cr\psi_{\{\alpha\in A:t_\alpha>0\},J}(x)\in X_{\{\alpha\in A:t_\alpha>0\}}^\mathrm{reg}\hfill\end{matrix}\right\}
\end{equation*}
The condition $\psi_{\{\alpha\in A:t_\alpha>0\},J}(x)\in X_{\{\alpha\in A:t_\alpha>0\}}^\mathrm{reg}$ ensures that we only deform to the normal cone of those zero sets $s_{J\setminus I'}^{-1}(0)$ which are cut out transversally ($I'\subseteq I$).  Clearly $(\partial X)_{I,J,A}\subseteq X_{I,J,A}$ is the subset where $x\in\partial X_J^\mathrm{reg}$ (the former being with respect to the restriction of $A$ to $\partial X$).  There are compatible maps:
\begin{equation}\label{pushforward}
X_{I,J,A}\times E_{A'\setminus A}\to X_{I',J',A'}\text{ for }I\subseteq I'\subseteq J'\subseteq J\subseteq A\subseteq A'
\end{equation}
given by $t_{A'\setminus A}=0$ and $x\mapsto\psi_{J',J}(x)$.  For $K\subseteq X$, we let $X_{I,J,A}^K\subseteq X_{I,J,A}$ denote the subspace where $e=0$ and $x\in\psi_{\varnothing J}^{-1}(K)$.  Note that $\Gamma_A$ acts on $X_{I,J,A}$ (acting on $X_J^\mathrm{reg}$ via the projection $\Gamma_A\to\Gamma_J$ and on $E_A$).

Let $I$ be a finite subset of an implicit atlas $A$.  We define:
\begin{equation}
C_\bullet(E;I):=C_{\dim E_I+\bullet}(E_I,E_I\setminus 0;\mathfrak o_{E_I}^\vee)^{\Gamma_I}
\end{equation}
There is a canonical isomorphism $H_\bullet(E;I)=R$ (concentrated in degree zero), and we denote the canonical generator by $[E_I]\in H_\bullet(E;I)$.

