\end{equation}

To illustrate this distinction further, let us mention a problematic alternative version of \eqref{fredholmsectionchart}:
\begin{equation}\label{fredholmsectionchartwrong}
X_I:=\Bigl\{x\in\bigcap_{\alpha\in I}V_\alpha\Bigm|s(x)\in\Bigl(\bigoplus_{\alpha\in I}\lambda_\alpha\Bigr)(E_I)\Bigr\}
\end{equation}

This definition agrees with \eqref{fredholmsectionchart} if the following map is injective:
\begin{equation}\label{lambdatotal}
\bigoplus_{\alpha\in I}\lambda_\alpha:\bigcap_{\alpha\in I}V_\alpha\times\bigoplus_{\alpha\in I}E_\alpha\to p^{-1}\Bigl(\bigcap_{\alpha\in I}V_\alpha\Bigr)
\end{equation}
but in general it can be different, and indeed, if \eqref{lambdatotal} fails to be injective, the definition \eqref{fredholmsectionchartwrong} isn't particularly useful.  Note that this can occur even if we add the requirement that each $\lambda_\alpha$ be injective.

The importance of using the direct sum was independently observed by McDuff--Wehrheim \cite{mcduffwehrheim}, and it is implicit in Fukaya--Oh--Ohta--Ono \cite{foootechnicaldetails}.
\end{remark}

\subsubsection{Moduli space of pseudo-holomorphic curves}\label{constructJholimplicitatlasintro}

We now give an example of the construction of an implicit atlas on a moduli space of pseudo-holomorphic curves.  This construction can be fruitfully interpreted as a generalization\footnote{Moduli spaces of pseudo-holomorphic curves do not fit literally into the setting of \S\ref{constructFredholmimplicitatlasintro} (generalized appropriately to Banach manifolds/bundles) because of three main issues: gluing (nodal domain curves), orbifold structure (nontrivial isotropy groups), and varying complex structures on the domain (nondifferentiability of the reparameterization action).  The polyfolds project of Hofer--Wysocki--Zehnder aims to setup an infinite-dimensional Fredholm framework in which moduli spaces of pseudo-holomorphic curves may be described.} of the construction from \S\ref{constructFredholmimplicitatlasintro}.

Specifically, we construct an implicit atlas $A$ on the moduli space of stable maps $\overline{\mathcal M}_{0,0}(X,B)$ (we fix a symplectic manifold $X$, a smooth $\omega$-tame almost complex structure $J$, and a homology class $B\in H_2(X;\mathbb Z)$).  The reader impatient for the full details may also wish to refer to \S\ref{gromovwittensection} where we give a full treatment.  Here we have simplified things by assuming that $(g,n)=(0,0)$, $\Gamma_\alpha=S_{r_\alpha}$ and $\overline{\mathcal M}_\alpha=\overline{\mathcal M}_{0,r_\alpha}$ (which is a smooth manifold!).

We define $A$ to be the set of all \emph{thickening datums} where a thickening datum is a $4$-tuple $(r_\alpha,D_\alpha,E_\alpha,\lambda_\alpha)$ consisting of:
\begin{rlist}
\item An integer $r_\alpha>2$; let $\Gamma_\alpha:=S_{r_\alpha}$.
\item A smooth compact codimension two submanifold $D_\alpha\subseteq X$ with boundary.
\item A finite-dimensional $\mathbb R[S_{r_\alpha}]$-module $E_\alpha$.
\item A $S_{r_\alpha}$-equivariant map $\lambda_\alpha:E_\alpha\to C^\infty(\overline{\mathcal C}_{0,r_\alpha}\times X,\Omega^{0,1}_{\overline{\mathcal C}_{0,r_\alpha}/\overline{\mathcal M}_{0,r_\alpha}}\otimes_\mathbb C TX)$ (where $\overline{\mathcal C}_{0,r_\alpha}\to\overline{\mathcal M}_{0,r_\alpha}$ is the universal family over the Deligne--Mumford moduli space) supported away from the nodes and marked points of the fibers.
\end{rlist}
Let us remark that the analogue of the open set $V_\alpha$ from \S\ref{constructFredholmimplicitatlasintro} is the set of maps $u:C\to X$ satisfying the conditions appearing in (\ref{firstcondition}) below.

Now our thickening $\overline{\mathcal M}_{0,0}(X,B)_I$ (any finite $I\subseteq A$) is defined as the set of:
\begin{rlist}
\item\label{firstcondition}A smooth map $u:C\to X$ where $C$ is a nodal curve of genus $0$ so that for all $\alpha\in I$, we have $u\pitchfork D_\alpha$ (meaning $u^{-1}(\partial D_\alpha)=\varnothing$ and for all $p\in u^{-1}(D_\alpha)$, the differential $(du)_p:T_pC\to T_{u(p)}X/T_{u(p)}D_\alpha$ is surjective and $p$ is not a node of $C$) with $\#u^{-1}(D_\alpha)=r_\alpha$ such that adding these $r_\alpha$ intersections as marked points makes $C$ stable.
\item Elements $e_\alpha\in E_\alpha$ for all $\alpha\in I$
\item Labellings of $u^{-1}(D_\alpha)$ by $\{1,\ldots,r_\alpha\}$ for all $\alpha\in I$.
\end{rlist}
such that:
\begin{equation}\label{thickenedintro}
\bar\partial u+\sum_{\alpha\in I}\lambda_\alpha(e_\alpha)(\phi_\alpha,u)=0
\end{equation}

Now we consider the mapping cone of the following:
\begin{equation}\label{multichartcomplex}
\begin{matrix}
C_{\dim X_{\alpha\beta}-\bullet}(U_{\alpha,\alpha\beta}\times E_\beta,U_{\alpha,\alpha\beta}\times E_\beta\setminus U_\alpha\times 0)\cr\oplus\cr
C_{\dim X_{\alpha\beta}-\bullet}(E_\alpha\times U_{\beta,\alpha\beta},E_\alpha\times U_{\beta,\alpha\beta}\setminus 0\times U_\beta)
\end{matrix}
\to
\begin{matrix}
C_{\dim X_{\alpha\beta}-\bullet}(X_\alpha\times E_\beta,X_\alpha\times E_\beta\setminus U_\alpha\times 0)\cr\oplus\cr
C_{\dim X_{\alpha\beta}-\bullet}(Y_{\alpha\beta},Y_{\alpha\beta}\setminus 0\times[0,1]\times U_{\alpha\beta})\cr\oplus\cr
C_{\dim X_{\alpha\beta}-\bullet}(E_\alpha\times X_\beta,E_\alpha\times X_\beta\setminus 0\times U_\beta)
\end{matrix}
\end{equation}
The maps are simply pushforward along the maps of spaces (with appropriate signs):
\begin{align}
U_{\alpha,\alpha\beta}\times E_\beta&\hookrightarrow X_\alpha\times E_\beta\\
U_{\alpha,\alpha\beta}\times E_\beta&\hookrightarrow Y_{\alpha\beta}\quad\text{(isomorphism onto $t=1$ fiber)}\\
E_\alpha\times U_{\beta,\alpha\beta}&\hookrightarrow Y_{\alpha\beta}\quad\text{(isomorphism onto $t=0$ fiber)}\\
E_\alpha\times U_{\beta,\alpha\beta}&\hookrightarrow E_\alpha\times X_\beta
\end{align}
There is also an evident map from (the mapping cone of) \eqref{multichartcomplex} to $C_\bullet(E_\alpha\oplus E_\beta,E_\alpha\oplus E_\beta\setminus 0)$ (namely pushforward on the three factors on the right hand side and zero on the left hand side).

Now to complete the definition of the virtual fundamental cycle of $X$ using the mapping cone of \eqref{multichartcomplex}, we need an argument to show that its homology is canonically isomorphic to the \v Cech cohomology of $X$ (a sort of Poincar\'e duality isomorphism).  We discuss this next in \S\ref{homotopysheavesintrosec}.

\subsubsection{Homotopy \texorpdfstring{$\mathcal K$}{K}-sheaves in the theory of virtual fundamental cycles}\label{homotopysheavesintrosec}

As we have already mentioned, the central objects we use to understand virtual fundamental cycles are the \emph{virtual cochain complexes} $C^\bullet_\mathrm{vir}(X;A)$ (for example, the mapping cone of \eqref{multichartcomplex} plays the role of the virtual cochain complex in \S\ref{vfcmultiplecharts}).  A crucial ingredient in this approach is an isomorphism:
\begin{equation}\label{homotopyisogoal}
H^\bullet_\mathrm{vir}(X;A)=\check H^\bullet(X)
\end{equation}
In \S\ref{vfcsinglechart}, where we used $C^\bullet_\mathrm{vir}(X;A):=C_{\dim X_\alpha-\bullet}(X_\alpha,X_\alpha\setminus X)$, this isomorphism was simply (a strong form of) Poincar\'e duality.

Let us now discuss our general approach to the isomorphism \eqref{homotopyisogoal}, which we think of as a generalized form of Poincar\'e duality.  An efficient approach (in fact, the only approach known to the author) to constructing this isomorphism is through the language of homotopy $\mathcal K$-sheaves, and so this is the way we present it.  We develop the necessary sheaf-theoretic foundations in Appendix \ref{homologicalalgebrasection}, so the reader may also wish to refer to that section for more details.

As an introduction to the language of sheaves and homotopy sheaves, let us first use it to give a proof of ordinary Poincar\'e duality (in fact, a strong version for arbitrary compact subsets of a manifold).\footnote{An easier proof (using the fact that \v Cech cohomology satisfies the ``continuity axiom'') is available if $M$ has a smooth structure (along the lines of \cite[pp887--888 Lemmas 3.1 and 3.3]{pardonHS}).  This approach does not seem to apply to the more general setting we need to treat here.}  The following argument appears in full detail in Lemma \ref{poincareduality}.

Fix a closed manifold $M$ of dimension $n$.  For any compact subset $K\subseteq M$, let $\mathcal F^\bullet(K)$ denote the complex $C_{n-\bullet}(M,M\setminus K)$.  This object $\mathcal F^\bullet$ is a \emph{$\mathcal K$-presheaf\footnote{The prefix ``$\mathcal K$-'' indicates sections are given over compact sets instead of open sets.  For technical reasons, it is more convenient to work with $\mathcal K$-presheaves rather than presheaves, though at the conceptual level, the reader may safely ignore the difference.} of complexes} (or \emph{complex of $\mathcal K$-presheaves}) on $M$, which just means that we have natural maps $\mathcal F^\bullet(K)\to\mathcal F^\bullet(K')$ for $K\supseteq K'$, which are suitably compatible with each other.  Now $\mathcal F^\bullet$ satisfies the following key properties:
\begin{rlist}
\item(``$\mathcal F^\bullet$ is a homotopy $\mathcal K$-sheaf'') The total complex of the following double complex is acyclic:
\begin{equation}
\mathcal F^\bullet(K_1\cup K_2)\to\mathcal F^\bullet(K_1)\oplus\mathcal F^\bullet(K_2)\to\mathcal F^\bullet(K_1\cap K_2)
\end{equation}

Moreover, giving $\partial X$ the ``restriction to the boundary'' implicit atlas, there is a natural map:
\begin{equation}\label{introcoboundary}
C_\mathrm{vir}^{\bullet-1}(\partial X)\to C_\mathrm{vir}^\bullet(X\operatorname{rel}\partial)
\end{equation}
whose mapping cone is $C^\bullet_\mathrm{vir}(X)$ (by definition).  There are canonical isomorphisms:
\begin{align}
\label{HXisointro}H^\bullet_\mathrm{vir}(X)&\xrightarrow\sim\check H^\bullet(X;\mathfrak o_X)\\
\label{HXrelisointro}H^\bullet_\mathrm{vir}(X\operatorname{rel}\partial)&\xrightarrow\sim\check H^\bullet(X;\mathfrak o_{X\operatorname{rel}\partial})
\end{align}
where $\mathfrak o_X$ is the ``virtual orientation sheaf'' of $X$.  There is also a map:
\begin{equation}\label{thomintro}
C^\bullet_\mathrm{vir}(X\operatorname{rel}\partial)\xrightarrow{s_\ast}C_{\dim E_A-\bullet}(E_A,E_A\setminus 0)
\end{equation}
(which, when combined with \eqref{HXrelisointro}, can be thought of as pairing against the virtual fundamental cycle of $X$).  Now, there are also product maps:
\begin{equation}
C_\mathrm{vir}^\bullet(\mathcal X(p,q)\operatorname{rel}\partial)\otimes C_\mathrm{vir}^\bullet(\mathcal X(q,r)\operatorname{rel}\partial)\to C_\mathrm{vir}^\bullet([\mathcal X(p,q)\times\mathcal X(q,r)]\operatorname{rel}\partial)
\end{equation}
which, when combined with the concatenation maps \eqref{productmapexample} induce maps:
\begin{equation}\label{productmapfromIA}
C_\mathrm{vir}^\bullet(\mathcal X(p,q)\operatorname{rel}\partial)\otimes C_\mathrm{vir}^\bullet(\mathcal X(q,r)\operatorname{rel}\partial)\to C_\mathrm{vir}^\bullet(\partial\mathcal X(p,r))
\end{equation}
From construction, it is clear that the following diagram commutes:
\begin{equation}\label{productofVCandonEcompare}
\begin{tikzcd}
C_\mathrm{vir}^\bullet(\mathcal X(p,q)\operatorname{rel}\partial)\otimes C_\mathrm{vir}^\bullet(\mathcal X(q,r)\operatorname{rel}\partial)\ar{r}{\eqref{productmapfromIA}}\ar{d}{s_\ast\otimes s_\ast}&C_\mathrm{vir}^\bullet(\partial\mathcal X(p,r))\ar{d}{s_\ast}\\
C_\bullet(E_{\mathcal A(p,q)},E_{\mathcal A(p,q)}\setminus 0)\otimes C_\bullet(E_{\mathcal A(q,r)},E_{\mathcal A(q,r)}\setminus 0)\ar{r}&C_\bullet(E_{\mathcal A(p,r)},E_{\mathcal A(p,r)}\setminus 0)
\end{tikzcd}
\end{equation}
where the bottom map is simply the cartesian product on chains (recall that $\mathcal A(p,r)=\mathcal A(p,q)\sqcup\mathcal A(q,r)$).

Now, let us describe the construction of a boundary operator $d:\mathbb Z[\mathcal P]\to\mathbb Z[\mathcal P]$ given the flow category $(\mathcal P,\mathcal X)$ and its system of implicit atlases.  To define $d$, we need to choose:\footnote{That these should be contractible choices is suggested by the Dold--Thom--Almgren theorem \cite{almgren} \cite[p430]{gromovI}.}
\begin{rlist}
\item(``Chain level coherent orientations'') Cochains $\lambda(p,q)\in C^0_\mathrm{vir}(\mathcal X(p,q)\operatorname{rel}\partial)$ satisfying the following property.  Define:
\begin{equation}\label{boundarychainlevelcoherent}
\mu(p,r):=\sum_{p\prec q\prec r}\lambda(p,q)\cdot\lambda(q,r)\in C_\mathrm{vir}^0(\partial\mathcal X(p,r))
\end{equation}

There is a canonical map:
\begin{equation}\label{sastintrotvfcsec}
C^{d+\bullet}_\mathrm{vir}(X\operatorname{rel}\partial;A)\xrightarrow{s_\ast}C_{\dim E_A-\bullet}(E_A,E_A\setminus 0;\mathfrak o_{E_A}^\vee)^{\Gamma_A}
\end{equation}
which can be thought of as the (chain level) \emph{virtual fundamental cycle}.

To study the virtual cochain complexes (in particular, to construct the isomorphisms \eqref{HXiso}--\eqref{HXreliso}), we define complexes of $\mathcal K$-presheaves on $X$:
\begin{align}
K&\mapsto C^\bullet_\mathrm{vir}(K;A)\\
K&\mapsto C^\bullet_\mathrm{vir}(K\operatorname{rel}\partial;A)
\end{align}
whose global sections are the virtual cochain complexes.\footnote{Note that this is a certain abuse of notation, as $A$ is not an implicit atlas on $K\subsetneqq X$.}\footnote{Note that the map $s_\ast$ \eqref{sastintrotvfcsec} is global; it does not exist on $C^\bullet_\mathrm{vir}(K\operatorname{rel}\partial;A)$ for $K\subsetneqq X$ or on any $C^\bullet_\mathrm{vir}(K;A)$.}  We show that they are pure homotopy $\mathcal K$-sheaves, and that there are canonical isomorphisms of sheaves on $X$:
\begin{align}
H^0_\mathrm{vir}(-;A)&=\mathfrak o_X\\
H^0_\mathrm{vir}(-\operatorname{rel}\partial;A)&=\mathfrak o_{X\operatorname{rel}\partial}
\end{align}
The isomorphisms \eqref{HXiso}--\eqref{HXreliso} then follow from Proposition \ref{cechcohomologypurehomotopysheaf}.

The fact that the virtual cochain complexes are the global sections of pure homotopy $\mathcal K$-sheaves with known $H^0$ will also play a key role in the applications of the VFC package.

Another useful fact we prove here is that the isomorphisms \eqref{HXiso}--\eqref{HXreliso} are compatible with the long exact sequence of the pair $(X,\partial X)$ in $\check H^\bullet$ and a corresponding long exact sequence of $H^\bullet_\mathrm{vir}$.

\subsection{Orientations}\label{virtorsheaf}

Recall the notion of the orientation sheaf of a topological manifold (resp.\ with boundary) given in Definition \ref{manordef}.

\begin{definition}[Orientation module of a vector space]
Let $E$ be a finite-dimensional vector space over $\mathbb R$.  We let $\mathfrak o_E$ denote the orientation module of $E$, namely $H_{\dim E}(E,E\setminus 0)$ (a free $R$-module of rank $1$).\footnote{According to the previous definition, we should really call this $(\mathfrak o_E)_0$ (the stalk at $0\in E$ of the orientation sheaf of $E$ considered as a manifold), though we do not anticipate this abuse causing any particular confusion.}
\end{definition}

\begin{definition}[Locally orientable implicit atlas]\label{IAlocalorient}
Let $X$ be a space with implicit atlas $A$ with boundary.  We say that $A$ is \emph{locally orientable}\footnote{This is analogous to the notion of an orbifold being locally orientable.} iff for every $I\subseteq A$ and every $x\in(s_I|X_I^\mathrm{reg})^{-1}(0)$, the stabilizer $(\Gamma_I)_x$ acts trivially on $(\mathfrak o_{X_I^\mathrm{reg}})_x\otimes\mathfrak o_{E_I}^\vee$ (this action is always by a sign $(\Gamma_I)_x\to\{\pm 1\}$).  This notion is independent of the ring $R$ (due to our restriction that $\#\Gamma_\alpha$ be invertible in $R$).
\end{definition}

\begin{definition}[Virtual orientation sheaf $\mathfrak o_X$ of a space with implicit atlas]\label{IAorientationsheaf}
Let $X$ be a space with locally orientable implicit atlas $A$ with boundary.  Then there exists a sheaf $\mathfrak o_{X,A}$ on $X$ equipped with $\Gamma_I$-equivariant isomorphisms $\psi_{\varnothing I}^\ast\mathfrak o_{X,A}\xrightarrow\sim\mathfrak o_{X_I^\mathrm{reg}}\otimes\mathfrak o_{E_I}^\vee$ over $(s_I|X_I^\mathrm{reg})^{-1}(0)$ for every $I\subseteq A$, which are compatible with the maps $\psi_{IJ}$.  We call $\mathfrak o_{X,A}$ the \emph{virtual orientation sheaf} of $X$ (it is unique up to unique isomorphism); it is locally isomorphic to the constant sheaf $\underline R$.  We write $\mathfrak o_X$ for $\mathfrak o_{X,A}$ when the atlas is clear from context.  We let $\mathfrak o_{X\operatorname{rel}\partial}:=j_!j^\ast\mathfrak o_X$ where $j:X\setminus\partial X\hookrightarrow X$.
\end{definition}

\subsection{Virtual cochain complexes \texorpdfstring{$C^\bullet_\mathrm{vir}(X;A)$}{C\_vir(X;A)} and \texorpdfstring{$C^\bullet_\mathrm{vir}(X\operatorname{rel}\partial;A)$}{C\_vir(X rel d;A)}}\label{Fsheafdefsec}

\begin{definition}[Deformation to the normal cone]
Let $X$ be a space with finite implicit atlas $A$ with boundary.  For $I\subseteq J\subseteq A$, we define:
\begin{equation*}
X_{I,J,A}:=\left\{(e,t,x)\in E_A\times\mathbb R_{\geq 0}^A\times X_J^\mathrm{reg}\;\middle|\;\begin{matrix}t_\alpha=0\text{ for }\alpha\in A\setminus I\hfill\cr s_\alpha(x)=t_\alpha e_\alpha\text{ for }\alpha\in J\hfill\cr\psi_{\{\alpha\in A:t_\alpha>0\},J}(x)\in X_{\{\alpha\in A:t_\alpha>0\}}^\mathrm{reg}\hfill\end{matrix}\right\}
\end{equation*}

There are compatible maps:
\begin{equation}\label{pushforward}
X_{I,J,A}\times E_{A'\setminus A}\to X_{I',J',A'}\text{ for }I\subseteq I'\subseteq J'\subseteq J\subseteq A\subseteq A'
\end{equation}
given by $t_{A'\setminus A}=0$ and $x\mapsto\psi_{J',J}(x)$.  For $K\subseteq X$, we let $X_{I,J,A}^K\subseteq X_{I,J,A}$ denote the subspace where $e=0$ and $x\in\psi_{\varnothing J}^{-1}(K)$.  Note that $\Gamma_A$ acts on $X_{I,J,A}$ (acting on $X_J^\mathrm{reg}$ via the projection $\Gamma_A\to\Gamma_J$ and on $E_A$).
\end{definition}

\begin{remark}[Chains and cochains]\label{chainfixing}
We use $C_\bullet(X)$ (resp.\ $C^\bullet(X)$) to denote singular simplicial chains (resp.\ cochains) on a space $X$, and we use $C_\bullet(X,Y)$ to denote the cokernel of $C_\bullet(Y)\hookrightarrow C_\bullet(X)$ for $Y\subseteq X$ (``relative chains'').

Let us also recall the ``Eilenberg--Zilber map'' $C_\bullet(X)\otimes C_\bullet(Y)\to C_\bullet(X\times Y)$ for spaces $X$ and $Y$, corresponding to the standard subdivision of $\Delta^n\times\Delta^m$ into $\binom{n+m}n$ copies of $\Delta^{n+m}$.  The Eilenberg--Zilber map is associative (in the sense that it gives rise to a unique map $C_\bullet(X)\otimes C_\bullet(Y)\otimes C_\bullet(Z)\to C_\bullet(X\times Y\times Z)$) and commutative (in the sense that the following diagram commutes:
\begin{equation}\label{chainproductcommutes}
\begin{CD}
C_\bullet(X)\otimes C_\bullet(Y)@>>>C_\bullet(X\times Y)\cr
@VVV@VVV\cr
C_\bullet(Y)\otimes C_\bullet(X)@>>>C_\bullet(Y\times X)
\end{CD}
\end{equation}
for all $X$ and $Y$).  We should point out that this commutativity fails for some other common models of singular chains, for example singular cubical chains (modulo degeneracies).
\end{remark}

\begin{remark}[Independence of chain model]\label{independenceofchainmodel}
The particular choice of \emph{singular simplicial} chains is not particularly important.  The virtual fundamental classes, etc.\ resulting from our theory should be unchanged by using any other model of singular chains.  This independence would follow immediately (and all issues about finding chain models with good chain level functoriality properties would go away) if we setup the VFC package using $\infty$-categories.
\end{remark}

\begin{definition}[Fundamental cycles of vector spaces]
Let $I$ be a finite subset of an implicit atlas $A$.  We define:
\begin{equation}
C_\bullet(E;I):=C_{\dim E_I+\bullet}(E_I,E_I\setminus 0;\mathfrak o_{E_I}^\vee)^{\Gamma_I}
\end{equation}

For any compact $K\subseteq X$, we define:
\begin{align}
\label{CcomplexcriticaldefI}C^\bullet_\mathrm{vir}(K\operatorname{rel}\partial;A)_{IJ}&:=C_{d+\dim E_A-\bullet}(X_{I,J,A},X_{I,J,A}\setminus X_{I,J,A}^K;\mathfrak o_{E_A}^\vee)^{\Gamma_A}\\
\label{CcomplexcriticaldefII}C^\bullet_\mathrm{vir}(K;A)_{IJ}&:=\left[\begin{matrix}C_{d+\dim E_A-1-\bullet}((\partial X)_{I,J,A},(\partial X)_{I,J,A}\setminus(\partial X)_{I,J,A}^{K\cap\partial X};\mathfrak o_{E_A}^\vee)^{\Gamma_A}\hfill\cr\downarrow\cr C_{d+\dim E_A-\bullet}(X_{I,J,A},X_{I,J,A}\setminus X_{I,J,A}^K;\mathfrak o_{E_A}^\vee)^{\Gamma_A}\hfill\end{matrix}\right]
\end{align}

There are canonical maps:
\begin{align}
\label{Erelpartialpullback}C^\bullet_\mathrm{vir}(K\operatorname{rel}\partial;A)_{IJ}&\to C^\bullet_\mathrm{vir}(K;A)_{IJ}\\
\label{Ethompushforward}C^{d+\bullet}_\mathrm{vir}(X\operatorname{rel}\partial;A)_{IJ}&\xrightarrow{s_\ast}C_{-\bullet}(E;A)\\
\label{Epushforward1}\hspace{1.5in}C^\bullet_\mathrm{vir}(-;A)_{IJ}&\to C^\bullet_\mathrm{vir}(-;A)_{I',J'}\text{ for }I\subseteq I'\subseteq J'\subseteq J
\end{align}
(\eqref{Ethompushforward} is induced by the projection $X_{I,J,A}\to E_A$, and \eqref{Epushforward1} is induced by \eqref{pushforward} with $A=A'$).  These are compatible with each other in that certain obvious diagrams commute.
\end{definition}

\begin{definition}[Virtual cochain complexes $C^\bullet_\mathrm{vir}(-;A)$ and $C^\bullet_\mathrm{vir}(-\operatorname{rel}\partial;A)$]\label{Ccomplexdef}
Let $X$ be a space with finite implicit atlas $A$ of dimension $d$ with boundary.  For any compact $K\subseteq X$, we define:
\begin{align}
\label{CvirdefI}C^\bullet_\mathrm{vir}(K;A)&:=\operatornamewithlimits{hocolim}_{I\subseteq J\subseteq A}C^\bullet_\mathrm{vir}(K;A)_{IJ}\\
\label{CvirdefII}C^\bullet_\mathrm{vir}(K\operatorname{rel}\partial;A)&:=\operatornamewithlimits{hocolim}_{I\subseteq J\subseteq A}C^\bullet_\mathrm{vir}(K\operatorname{rel}\partial;A)_{IJ}
\end{align}

There are canonical maps:
\begin{align}
\label{Frelpartialpullback}C^\bullet_\mathrm{vir}(K\operatorname{rel}\partial;A)&\to C^\bullet_\mathrm{vir}(K;A)\\
\label{Fpushforward}C^{d+\bullet}_\mathrm{vir}(X\operatorname{rel}\partial;A)&\xrightarrow{s_\ast}C_{-\bullet}(E;A)
\end{align}
(induced by \eqref{Erelpartialpullback}--\eqref{Ethompushforward}).  More precisely, \eqref{Fpushforward} is given by \eqref{Ethompushforward} on the $p=0$ part of the $\operatornamewithlimits{hocolim}$ and is zero on the rest.
\end{definition}

\begin{definition}[Maps $C^\bullet_\mathrm{vir}(-;A)\to C^\bullet_\mathrm{vir}(-;A')$]
Let $X$ be a space with finite implicit atlases $A\subseteq A'$ with boundary.  There are canonical maps:
\begin{equation}
\label{Epushforward1more}C^\bullet_\mathrm{vir}(-;A)_{IJ}\otimes C_{-\bullet}(E;A'\setminus A)\to C^\bullet_\mathrm{vir}(-;A')_{I',J'}\text{ for }I\subseteq I'\subseteq J'\subseteq J\subseteq A\subseteq A'
\end{equation}
induced by \eqref{pushforward} (of which \eqref{Epushforward1} is a special case).  These are compatible with each other, and thus extend to the homotopy colimit over $I\subseteq J\subseteq A$.  Hence we get canonical maps:
\begin{equation}
\label{Fpushforward1}C^\bullet_\mathrm{vir}(-;A)\otimes C_{-\bullet}(E;A'\setminus A)\to C^\bullet_\mathrm{vir}(-;A')
\end{equation}
which are compatible with \eqref{Frelpartialpullback}--\eqref{Fpushforward}.
\end{definition}

Note that all of the complexes defined here are free $R$-modules (this follows from our assumption that $\#\Gamma_\alpha$ be invertible in $R$) and that everything in sight is compatible with base change $\otimes_RS$ for ring homomorphisms $R\to S$.

\subsection{Isomorphisms \texorpdfstring{$H^\bullet_\mathrm{vir}(X;A)=\check H^\bullet(X;\mathfrak o_X)$}{H\_vir(X;A)=H(X;o\_X)} (also \texorpdfstring{$\operatorname{rel}\partial$}{rel d})}\label{Fsheafcechsimplesec}

\begin{lemma}[$C^\bullet_\mathrm{vir}(-;A)_{IJ}$ are pure homotopy $\mathcal K$-sheaves]\label{CSTpure}
Let $X$ be a space with finite locally orientable implicit atlas $A$ with boundary.  Then $C^\bullet_\mathrm{vir}(-;A)_{IJ}$ and $C^\bullet_\mathrm{vir}(-\operatorname{rel}\partial;A)_{IJ}$ are pure homotopy $\mathcal K$-sheaves on $X$.  Furthermore, there are canonical isomorphisms of sheaves on $X$:
\begin{align}
\label{EisoI}H^0_\mathrm{vir}(-;A)_{IJ}&=j_!j^\ast\mathfrak o_X\\
\label{EisoII}H^0_\mathrm{vir}(-\operatorname{rel}\partial;A)_{IJ}&=j_!j^\ast\mathfrak o_{X\operatorname{rel}\partial}
\end{align}
where $j:V_I\cap V_J\hookrightarrow X$ for $V_I:=\psi_{\varnothing I}((s_I|X_I^\mathrm{reg})^{-1}(0))\subseteq X$ (an open subset).
\end{lemma}

\begin{proof}
Applying Lemmas \ref{singularchainshomotopyKsheaf} and \ref{associatedgradedhomotopysheaf}, we see that $C^\bullet_\mathrm{vir}(-;A)_{IJ}$ and $C^\bullet_\mathrm{vir}(-\operatorname{rel}\partial;A)_{IJ}$ are both homotopy $\mathcal K$-sheaves.

Now let us calculate $H^\bullet_\mathrm{vir}(K;A)_{IJ}$ and $H^\bullet_\mathrm{vir}(K\operatorname{rel}\partial;A)_{IJ}$.  It follows from the submersion axiom that $X_{I,J,A}$ is a topological manifold of dimension $\operatorname{vdim}_AX+\dim E_A+\#I$ with boundary (not necessarily second countable or paracompact).\footnote{In fact, it carries a natural structure of a manifold with corners, which for the present purpose is mostly irrelevant.}  The boundary $\partial(X_{I,J,A})$ is a (not necessarily disjoint) union of two pieces, namely the locus where $x\in\partial X_J^\mathrm{reg}$ (which is precisely $(\partial X)_{I,J,A}$) and the locus where $t_\alpha=0$ for some $\alpha\in I$.  It is easy to see that the first piece $(\partial X)_{I,J,A}\subseteq\partial(X_{I,J,A})$ is a closed tamely embedded codimension zero submanifold with boundary.  Hence we may apply Poincar\'e--Lefschetz duality in the form of Lemma \ref{poincareduality} to see that:
\begin{align}
H^\bullet_\mathrm{vir}(K\operatorname{rel}\partial;A)_{IJ}&=\check H_c^{\bullet+\#I}(\psi_{\varnothing J}^{-1}(K\cap V_I\cap V_J)\times\mathbb R_{>0}^I,\mathfrak o_\mathbb R^{\otimes I}\otimes\mathfrak o_{E_J}^\vee\otimes\mathfrak o_{X_J^\mathrm{reg}\operatorname{rel}\partial})^{\Gamma_A}\\
H^\bullet_\mathrm{vir}(K;A)_{IJ}&=\check H_c^{\bullet+\#I}(\psi_{\varnothing J}^{-1}(K\cap V_I\cap V_J)\times\mathbb R_{>0}^I,\mathfrak o_\mathbb R^{\otimes I}\otimes\mathfrak o_{E_J}^\vee\otimes\mathfrak o_{X_J^\mathrm{reg}})^{\Gamma_A}
\end{align}

The regular locus $X_I^\mathrm{reg}\subseteq X_I$ is the locus where $X_I$ is ``cut out transversally''; more precisely, $(x,\{e_\alpha\}_{\alpha\in I})\in X_I$ is in $X_I^\mathrm{reg}$ iff the following map is surjective:
\begin{equation}
\Bigl(ds+\sum_{\alpha\in I}d\lambda_\alpha(\cdot,e_\alpha)\Bigr)\oplus\bigoplus_{\alpha\in I}\lambda_\alpha(x,\cdot):T_xB\oplus\bigoplus_{\alpha\in I}E_\alpha\to E_x
\end{equation}
The transversality axioms are an easy exercise.  Thus $A$ is indeed an implicit atlas on $X$.

Since everything here is in the smooth category, $A$ is in fact a smooth implicit atlas.
\end{definition}

\begin{definition}[Euler class]
Let $B$ be a space equipped with a vector bundle $p:E\to B$ of rank $k$.  This induces a canonical locally constant sheaf $\mathfrak o_E$ on $B$ whose stalk at $b\in B$ is $\mathfrak o_{E_b}$.  Let $\tau_E\in H^k(E,E\setminus 0;p^\ast\mathfrak o_E)$ denote the Thom class of $E$ (characterized uniquely by the property that its restriction to any local trivialization $\mathbb R^n\times U\to U$ is the pullback of the tautological class in $H^n(\mathbb R^n,\mathbb R^n\setminus 0;\mathfrak o_{\mathbb R^n})$).

The \emph{Euler class} $e(E)\in H^k(B;\mathfrak o_E)$ is $s^\ast\tau_E$ where $s:B\to E$ is any section.  Any two sections are homotopic, so $e(E)$ is well-defined.  For any section $s:B\to E$ with $s^{-1}(0)$ compact, the \emph{Euler class with compact support} $e_c(E,s)\in H^k_c(B;\mathfrak o_E)$ is $s^\ast\tau_E$.  If $s_0$ and $s_1$ are homotopic through a section $\tilde s:B\times[0,1]\to E$ with compact support, then $e_c(E,s_0)=e_c(E,s_1)$.  The natural map $H^k_c(B;\mathfrak o_E)\to H^k(B;\mathfrak o_E)$ sends the Euler class with compact support to the Euler class.
\end{definition}

\begin{remark}
The Euler class with compact support can be nonzero even for the trivial vector bundle.
\end{remark}

\begin{proposition}\label{actuallygiveseulerclass}
Let $B$ be a smooth manifold, let $p:E\to B$ be a smooth vector bundle, and let $s:B\to E$ be a smooth section with $s^{-1}(0)$ compact.  Consider the implicit atlas $A$ on $X:=s^{-1}(0)$ from Definition \ref{IAonvectorbundlezeroset}.  Then there is a canonical isomorphism of sheaves $\mathfrak o_X=\mathfrak o_B\otimes\mathfrak o_E^\vee$ on $X$ (in particular, $A$ is locally orientable), and the image of $[X]^\mathrm{vir}$ in $H^{\dim B-\dim E}(B;\mathfrak o_B\otimes\mathfrak o_E^\vee)^\vee$ equals $e_c(E,s)\cap[B]$.
\end{proposition}

Note that $\check H^\bullet(X;\mathfrak o_X)=\varinjlim_{X\subseteq U}H^\bullet(U;\mathfrak o_B\otimes\mathfrak o_E^\vee)$ (direct limit over open neighborhoods $U\subseteq B$ of $X$), by the continuity axiom of \v Cech cohomology.  The proposition applies equally well with $U$ in place of $B$, and thus determines $[X]^\mathrm{vir}\in\check H^\bullet(X;\mathfrak o_X)^\vee$ uniquely (note the use of either Lemma \ref{sameassubatlas} or \ref{openreduction}).

\begin{proof}
The statement about orientation sheaves is a straightforward calculation which we omit.

Choose some smooth family of sections $\tilde s:B\times[0,1]\to E$ with $\tilde s^{-1}(0)$ compact, so that $\tilde s(\cdot,0)=s$ and $s_1:=\tilde s(\cdot,1)$ is transverse to the zero section.

Now $B\times[0,1]$ is a smooth manifold with boundary, so let $\tilde A$ be the implicit atlas on $\tilde X:=\tilde s^{-1}(0)$ from Definition \ref{IAonvectorbundlezeroset}.  Similarly, let $A'$ be the implicit atlas on $X':=(s')^{-1}(0)$.

Now we have two implicit atlases on $X$, namely $A$ and (the restriction to the boundary of) $\tilde A$.  On the other hand, we can exhibit $A$ as a subatlas of $\tilde A$ by the map on thickening datums sending $V_\alpha$ to $V_\alpha\times[0,1]$ and $\lambda_\alpha$ to its obvious extension.  Hence they induce the same virtual fundamental class (Lemma \ref{sameassubatlas}), so we may just write $[X]^\mathrm{vir}$ (dropping the subscript indicating which atlas we use).  The same reasoning applies to $X'$.

Now $\partial\tilde X=X\sqcup X'$, so we have $[X]^\mathrm{vir}=[X']^\mathrm{vir}$ as homology classes on $\tilde X$ (Lemmas \ref{disjointunionfc} and \ref{cobordismworks}).  Hence we have:
\begin{equation}
[X]^\mathrm{vir}=[X']^\mathrm{vir}
\end{equation}

We also specify isomorphisms of sheaves $\mathfrak o_{(X_I^\mathrm{reg})^{\leq\mathfrak s}}\otimes\mathfrak o_\mathfrak s\xrightarrow\sim\mathfrak o_{X_I^\mathrm{reg}}$ over $(X_I^\mathrm{reg})^{\leq\mathfrak s}$ which are compatible with $\psi_{IJ}$ and such that the following diagram commutes:
\begin{equation}
\begin{tikzcd}
\mathfrak o_{(X_I^\mathrm{reg})^{\leq\mathfrak s}}\otimes\mathfrak o_\mathfrak s\ar{r}\ar{d}&\mathfrak o_{X_I^\mathrm{reg}}\ar[equals]{d}\\
\mathfrak o_{(X_I^\mathrm{reg})^{\leq\mathfrak t}}\otimes\mathfrak o_\mathfrak t\ar{r}&\mathfrak o_{X_I^\mathrm{reg}}
\end{tikzcd}
\end{equation}
for $\operatorname{codim}(\mathfrak s\preceq\mathfrak t)=1$ (the left vertical map is the tensor product of the coboundary map $\mathfrak o_\mathfrak s\to\mathfrak o_\mathfrak t$ and the inverse of the boundary map $\mathfrak o_{(X_I^\mathrm{reg})^{\leq\mathfrak t}}\to\mathfrak o_{(X_I^\mathrm{reg})^{\leq\mathfrak s}}$).  In other words, we identify $\mathfrak o_\mathfrak s$ with the orientation line of the normal bundle of $(X_I^\mathrm{reg})^{\leq\mathfrak s}\subseteq X_I^\mathrm{reg}$, so that the coboundary maps $\mathfrak o_\mathfrak s\to\mathfrak o_\mathfrak t$ coincide with the geometric coboundary maps on normal bundles.

Given an implicit atlas with boundary and cell-like stratification $A$ on $(X,\partial X)\to(\mathcal S,\partial\mathcal S)$, we may obtain by restriction to the corresponding strata an implicit atlas with cell-like stratification on $\partial X\to\partial\mathcal S$ (empty boundary, tensor every orientation line with $\mathfrak o_\mathbb R$) and an implicit atlas with boundary and cell-like stratification on $(X^{\leq\mathfrak s},X^{<\mathfrak s})\to(\mathcal S^{\leq\mathfrak s},\mathcal S^{<\mathfrak s})$ (tensor every orientation line with $\mathfrak o_\mathfrak s^\vee$).
\end{definition}

\begin{remark}
There should be a slightly more general setting for the results of this section (and their proofs), which takes as input a weakened version of Definition \ref{celllikedef}.  For example, it is probably enough to require that in a neighborhood of any $p\in M$, the closure of any (local) component of $M^\mathfrak s$ is a manifold with boundary whose interior is this local component (this is satisfied by both stratifications in Example \ref{celllikecornerexample}); basically this allows ``non-embedded faces''.
\end{remark}

\subsection{Stratified virtual cochain complexes}\label{stratvirtcochainssec}

In this section, we apply the VFC package to obtain a ``stratum by stratum'' understanding of virtual fundamental cycles on a space with implicit atlas with cell-like stratification.  To do this, we build a complex out of the virtual cochain complexes associated to each stratum and then study the properties of this larger complex.  This construction can be viewed as a generalization of the definition of $C_\mathrm{vir}^\bullet(X;A)$ as the mapping cone $[C^\bullet_\mathrm{vir}(\partial X;A)\to C^\bullet_\mathrm{vir}(X\operatorname{rel}\partial;A)]$, and the main result here can be viewed as a generalization of Lemma \ref{compatibilityoflongexactsequence}.

\begin{example}\label{stratifiedchainsremark}
As a first step towards understanding the main construction of this section, let us first describe a similar construction in a more familiar setting.  Let $M$ be a topological manifold with cell-like stratification by $\mathcal S$.  Define:
\begin{equation}
C_\bullet(M;\mathcal S):=\bigoplus_{\mathfrak s\in\mathcal S}C_{\bullet-(\dim M-\dim\mathfrak s)}(M^{\leq\mathfrak s};\mathfrak o_M\otimes\mathfrak o_{M^{\leq\mathfrak s}}^\vee)
\end{equation}

Now there is a natural map:
\begin{align}\label{stratchainstousual}
C_\bullet(M;\mathcal S)&\to C_\bullet(M)\\
\bigoplus_{\mathfrak s\in\mathcal S}\gamma_\mathfrak s&\mapsto\sum_{\begin{smallmatrix}\mathfrak s\in\mathcal S\cr\dim\mathfrak s=\dim M\end{smallmatrix}}\gamma_\mathfrak s
\end{align}
(it follows from Lemma \ref{celllikelocalstructure} that this is a chain map) which we claim is a quasi-isomorphism.

To see that \eqref{stratchainstousual} is a quasi-isomorphism, observe that it is the map on global sections of a corresponding map of complexes of $\mathcal K$-presheaves $C_\bullet(M,M\setminus K;\mathcal S)\to C_\bullet(M,M\setminus K)$ on the one-point compactification $M_+$ of $M$.  Both are homotopy $\mathcal K$-sheaves by Lemma \ref{singularchainshomotopyKsheaf}.  Thus by Corollary \ref{homotopysheafcheckqionstalks}, it suffices to show that the map $C_\bullet(M,M\setminus p;\mathcal S)\to C_\bullet(M,M\setminus p)$ is a quasi-isomorphism for every $p\in M$.  This holds by the following local argument.  Note that $H_\bullet(M,M\setminus p;\mathcal S)$ is isomorphic to $\mathbb Z$ (to see this, consider the filtration by $\dim\mathfrak s$), so it suffices to construct a cycle in $C_\bullet(M,M\setminus p;\mathcal S)$ representing a generator of $\mathbb Z$ and show that its image in $H_\bullet(M,M\setminus p)=\mathbb Z$ is a generator.  Such a cycle may be constructed by induction on $\mathcal S$ (starting from the stratum containing $p$ and going up), and its image in $H_\bullet(M,M\setminus p)$ generates since its degree at $p$ coincides with its degree at any nearby point in an open stratum, which is one by construction.  A similar argument appears in Barraud--Cornea \cite[p670, Lemma 2.2]{barraudcornea}.

Thus we can think of $C_\bullet(M;\mathcal S)$ as a model for chains on $M$ (the reader should make sure they understand what this means geometrically).
\end{example}

\begin{definition}[Stratified virtual cochain complexes $C^\bullet_\mathrm{vir}(-,\mathcal S;A)$]\label{stratifiedvirtualdef}
Let $(X,\partial X)\to(\mathcal S,\partial\mathcal S)$ be equipped with a finite implicit atlas with boundary and cell-like stratification $A$.  For any compact $K\subseteq X$, we define:
\begin{equation}\label{virtualchainswithcornersdef}
C^\bullet_\mathrm{vir}(K,\mathcal S;A):=\bigoplus_{\mathfrak s\in\mathcal S}C^\bullet_\mathrm{vir}(K\cap X^{\leq\mathfrak s}\operatorname{rel}\partial;A)\otimes\mathfrak o_\mathfrak s
\end{equation}

}
\begin{equation}\label{coproductforA}
\mathcal A(\sigma,p,q)^{\geq\mathfrak s}:=\coprod_{\begin{smallmatrix}0\leq i_0<\cdots<i_m\leq n\cr(p',q')\in\mathcal P_{\sigma(i_0)}\times\mathcal P_{\sigma(i_m)}\cr\exists\mathfrak t\in\mathcal S_\mathcal X(\sigma,p,q)^{\geq\mathfrak s}\text{ containing }([i_0\ldots i_m],p',q')\end{smallmatrix}}\bar\A(\sigma|[i_0\ldots i_m],p',q')
\end{equation}

Hence it suffices to construct (functorially) $Q\mathcal W_\bullet(\sigma,p,q)$ fitting into the following commutative diagram:
\begin{equation}\label{cofibrantdefdiagram}
\begin{tikzcd}[column sep = huge]
\smash{\displaystyle\operatornamewithlimits{colim}_{\mathfrak s\in\partial\mathcal S_\mathcal W(\sigma,p,q)}}Q\mathcal W_\bullet(\sigma,p,q,\mathfrak s)\ar{d}\ar[dashed, tail]{r}{\text{product/face}}&?\exists\,Q\mathcal W_\bullet(\sigma,p,q)\ar[dashed, two heads]{d}{\sim}\\
\displaystyle\operatornamewithlimits{colim}_{\mathfrak s\in\partial\mathcal S_\mathcal W(\sigma,p,q)}\mathcal W_\bullet(\sigma,p,q,\mathfrak s)\ar{r}{\text{product/face}}&\mathcal W_\bullet(\sigma,p,q)
\end{tikzcd}
\end{equation}
Now we define $Q\mathcal W_\bullet(\sigma,p,q)$ to be the mapping cylinder of the diagonal composition.  Since the domain and codomain of this map are both cofibrant (for the domain, use Lemma \ref{cofibranthaslotsofcofibrations}, which applies since $\mathcal S_\mathcal W(\sigma,p,q)$ has been assumed to be finite), it follows that the top map is a cofibration and that $Q\mathcal W_\bullet(\sigma,p,q)$ is cofibrant.  The product/face maps with target $Q\mathcal W_\bullet(\sigma,p,q)$ are defined using the top horizontal map; they are compatible since by construction they factor through the colimit in the upper left corner.

Certainly $\operatorname{supp} Q\mathcal W_\bullet\supseteq\operatorname{supp}\mathcal W_\bullet$.  Conversely, suppose $Q\mathcal W_\bullet(\sigma,p,q)$ is nonzero.  Then either $\mathcal W_\bullet(\sigma,p,q)\ne 0$ (so $(\sigma,p,q)\in\operatorname{supp}\mathcal W_\bullet$), or $Q\mathcal W_\bullet(\sigma,p,q,\mathfrak s)\ne 0$ for some $\mathfrak s\in\partial\mathcal S(\sigma,p,q)$ (so by induction, the triples comprising $\mathfrak s$ are in $\operatorname{supp}\mathcal W_\bullet$, and hence so is $(\sigma,p,q)$).
\end{definition}

\begin{lemma}\label{tensorproductvanishing}
Let $\{C_\bullet^k\}_{k=1}^n$ be cofibrant complexes over $\mathbb Z$ such that $H_iC_\bullet^k=0$ for $i<0$.  Then $H_i(\bigotimes_{k=1}^nC_\bullet^k)=0$ for $i<0$.
\end{lemma}

\begin{proof}
Since the tensor product of projective modules is projective, we may use induction to reduce to the case $k=2$.

Thus, we have two cofibrant complexes $A_\bullet$ and $B_\bullet$ with $H_iA_\bullet=H_iB_\bullet=0$ for $i<0$ and we would like to conclude that $H_i(A_\bullet\otimes B_\bullet)=0$ for $i<0$.  This follows from the K\"unneth theorem, specifically in the form of \cite[p301, Theorem 9.16]{osborne} or \cite[p679, Theorem 10.81]{rotman} (both of which apply because $\operatorname{Tor}^i_\mathbb Z(\cdot,\cdot)=0$ for $i>1$).\footnote{If we were assuming $A_\bullet$ and $B_\bullet$ to be bounded below, then we could apply the K\"unneth spectral sequence $\bigoplus_{i+j=q}\operatorname{Tor}_p(H_iA_\bullet,H_jB_\bullet)\Rightarrow H_{p+q}(A_\bullet\otimes B_\bullet)$ (see \cite[p686, Theorem 10.90]{rotman}) to reach the desired conclusion without any assumptions on the ground ring.}
\end{proof}

\begin{lemma}\label{Hzeroofcofibrantcolimit}
Let $\mathcal W_\bullet$ be a cofibrant $\mathsf{F}$-module complex over $\mathbb Z$ such that $H_i\mathcal W_\bullet=0$ for $i<0$.  Then for any finite downward closed subset $\mathcal S\subseteq\mathcal S_\mathcal W(\sigma,p,q)$, the map:
\begin{equation}\label{tocolimitsurjective}
H_i\bigoplus_{\mathfrak s\in\mathcal S}\mathcal W_\bullet(\sigma,p,q,\mathfrak s)\twoheadrightarrow H_i\operatornamewithlimits{colim}_{\mathfrak s\in\mathcal S}\mathcal W_\bullet(\sigma,p,q,\mathfrak s)
\end{equation}
is surjective for $i\leq 0$.  Moreover, both sides vanish for $i<0$.
\end{lemma}

\begin{proof}
Let us abbreviate $A_\mathfrak s:=\mathcal W_\bullet(\sigma,p,q,\mathfrak s)$.  Since $A_\mathfrak s$ is a tensor product of various $\mathcal W_\bullet(\sigma',p',q')$, it follows (using Lemma \ref{tensorproductvanishing}) that $H_iA_\mathfrak s$ for $i<0$, so the left hand side of \eqref{tocolimitsurjective} vanishes for $i<0$.  Hence it remains just to show that \eqref{tocolimitsurjective} is surjective for $i\leq 0$.

We proceed by induction on the cardinality of $\mathcal S$, the case $\mathcal S=\varnothing$ being clear.  Let $\mathfrak s_0\in\mathcal S$ be any maximal element.  Now $\operatornamewithlimits{colim}_{\mathfrak s\in\mathcal S}A_\mathfrak s$ is the colimit of \eqref{colimitdiagrambuildup}; it follows that we have the following exact sequence:
\begin{equation}\label{colimitSEScofibrant}
0\to\operatornamewithlimits{colim}_{\begin{smallmatrix}\mathfrak s\in\mathcal S\cr\mathfrak s\prec\mathfrak s_0\end{smallmatrix}}A_\mathfrak s\to A_{\mathfrak s_0}\oplus\operatornamewithlimits{colim}_{\mathfrak s\in\mathcal S\setminus\mathfrak s_0}A_\mathfrak s\to\operatornamewithlimits{colim}_{\mathfrak s\in\mathcal S}A_\mathfrak s\to 0
\end{equation}

Then there is a natural short exact sequence:
\begin{equation}
0\to\operatorname{Ext}^1(H_{i-1}A_\bullet,\mathbb Z)\to H^i\operatorname{Hom}(A_\bullet,\mathbb Z)\to\operatorname{Hom}(H_iA_\bullet,\mathbb Z)\to 0
\end{equation}
\end{lemma}

\begin{proof}
Well-known.
\end{proof}

\begin{lemma}[Extending cocycles along a cofibration]\label{cocycleextendinglemma}
Suppose we have the following commuting diagrams (solid arrows) of complexes over $\mathbb Z$ and their homology (where $\mathbb Z$ is concentrated in degree zero):
\begin{equation}
\begin{tikzcd}
A_\bullet\ar[tail]{r}\ar{d}&\tilde A_\bullet\ar[dashed]{dl}\\
\mathbb Z
\end{tikzcd}
\overset{H_\bullet}\Longrightarrow
\begin{tikzcd}
H_\bullet A_\bullet\ar{r}\ar{d}&H_\bullet\tilde A_\bullet\ar{dl}\\
\mathbb Z
\end{tikzcd}
\end{equation}
where $A_\bullet$ and $\tilde A_\bullet$ are cofibrant and $H_{-1}A_\bullet=0$.  Then there exists a dashed arrow compatible with the rest of the diagram.
\end{lemma}

\begin{proof}
By Lemma \ref{universalcoefficient}, we have:
\begin{align}
\label{notildeiso}H^0\operatorname{Hom}(A_\bullet,\mathbb Z)&\xrightarrow\sim\operatorname{Hom}(H_0A_\bullet,\mathbb Z)\\
\label{tildesurj}H^0\operatorname{Hom}(\tilde A_\bullet,\mathbb Z)&\twoheadrightarrow\operatorname{Hom}(H_0\tilde A_\bullet,\mathbb Z)
\end{align}
Let $f:A_0\to\mathbb Z$ denote the vertical map in the first diagram.  Using the surjectivity of \eqref{tildesurj}, there exists a cocycle $\tilde f:\tilde A_0\to\mathbb Z$ giving the desired map on homology.  Denote by $i:A_\bullet\rightarrowtail\tilde A_\bullet$ the inclusion.  Now by the commutativity of the second diagram, the difference $f-\tilde fi$ acts as zero on $H_0A_\bullet$.  Since \eqref{notildeiso} is an isomorphism, this difference is thus a coboundary $\delta g$ for some $g:A_{-1}\to\mathbb Z$.  Now extend $g$ to $\tilde g:\tilde A_{-1}\to\mathbb Z$ (using the fact that $A_{-1}\rightarrowtail\tilde A_{-1}$ splits) and let the dotted arrow be $\tilde f+\delta\tilde g$.
\end{proof}

\subsection{Resolution \texorpdfstring{$\tilde Z_\bullet\to Z_\bullet$}{tilde Z to Z}}

We now introduce the space $\pi:\tilde Z_\bullet\to Z_\bullet$ (depending on a flow category diagram $\mathcal X/Z_\bullet$ equipped with an implicit atlas and coherent orientations) which one may think of as parameterizing coherent choices of virtual fundamental cycles over all of the flow spaces $\mathcal X(\sigma,p,q)$.

The main result is that $\pi:\tilde Z_\bullet\to Z_\bullet$ is a trivial Kan fibration.

\begin{definition}[System of chains]\label{systemofcycles}
Let $\mathcal W^\bullet$ be an $\mathsf{F}$-module complex with each $\mathcal S_\mathcal W(\sigma,p,q)$ finite.  A \emph{system of chains} $\lambda\in\mathcal W^\bullet$ (of degree $d(\sigma,p,q)$) is a collection of elements $\lambda_{\sigma,p,q}\in\mathcal W^{d(\sigma,p,q)}(\sigma,p,q)$ satisfying $d\lambda_{\sigma,p,q}=\mu_{\sigma,p,q}$ where:
\begin{equation}\label{lambdamaster}
\mu_{\sigma,p,r}:=\sum_{k=0}^n\sum_{q\in\mathcal P_{\sigma(k)}}(-1)^{k+\operatorname{gr}(p)}\lambda_{\sigma|[0\ldots k],p,q}\cdot\lambda_{\sigma|[k\ldots n],q,r}-\sum_{k=1}^{n-1}(-1)^{k+\operatorname{gr}(p)}\lambda_{\sigma|[0\ldots\hat k\ldots n],p,r}\in\mathcal W^\bullet(\sigma,p,r)
\end{equation}

Now for a simplex $\sigma\in\tilde Z_n$, we aim to define the map $f_\sigma:R[[\mathcal P_{\sigma(0)}]]\to R[[\mathcal P_{\sigma(n)}]]$ by the formula:
\begin{equation}\label{diagramndgformula}
f_\sigma(p):=\sum_{q\in\mathcal P_{\sigma(n)}}([[E]]_{\sigma,p,q}\otimes\operatorname{id}_R)(\tilde\lambda_{\sigma,p,q})\cdot q
\end{equation}

For any $S^1$-invariant compact $K\subseteq X$, we define:
\begin{align}
\label{bigSSpartial}C^\bullet_{S^1,\mathrm{vir}}(K;A)_{IJ}\quad&C^\bullet_{S^1,\mathrm{vir}}(K\operatorname{rel}\partial;A)_{IJ}\\
\label{bigSS}C^\bullet_{S^1,\mathrm{vir}}(K;A)\phantom{_{IJ}}\quad&C^\bullet_{S^1,\mathrm{vir}}(K\operatorname{rel}\partial;A)
\end{align}
as in Definitions \ref{CSTcomplexdef}--\ref{Ccomplexdef}, except using $C_{\bullet-1}^{S^1}$ in place of $C_\bullet$ in \eqref{CcomplexcriticaldefI}--\eqref{CcomplexcriticaldefII}.  It is clear that \eqref{bigSSpartial}--\eqref{bigSS} are complexes of $\mathcal K$-presheaves on $X/S^1$ (replace $K$ with $\pi^{-1}(K)$, where $\pi:X\to X/S^1$).  The Gysin map \eqref{pishriek} induces ``comparison maps'':
\begin{equation}\label{CSStimesSS}
C^\bullet_{S^1,\mathrm{vir}}(-;A)_{(IJ)}\to C^\bullet_\mathrm{vir}(-;A)_{(IJ)}
\end{equation}
for all flavors \eqref{bigSSpartial}--\eqref{bigSS}

Analogously with \eqref{Erelpartialpullback}--\eqref{Epushforward1} and \eqref{Frelpartialpullback}--\eqref{Fpushforward}, there are natural maps (compatible with \eqref{CSStimesSS}):
\begin{align}
C^\bullet_{S^1,\mathrm{vir}}(K\operatorname{rel}\partial;A)_{IJ}&\to C^\bullet_{S^1,\mathrm{vir}}(K;A)_{IJ}\\
C^{d+\bullet}_{S^1,\mathrm{vir}}(X\operatorname{rel}\partial;A)_{IJ}&\xrightarrow{s_\ast}C_{-\bullet-1}^{S^1}(E;A)\\
C^\bullet_{S^1,\mathrm{vir}}(-;A)_{IJ}&\to C^\bullet_{S^1,\mathrm{vir}}(-;A)_{I',J'}\\
\label{CSSrelpartialpullback}C^\bullet_{S^1,\mathrm{vir}}(K\operatorname{rel}\partial;A)&\to C^\bullet_{S^1,\mathrm{vir}}(K;A)\\
\label{CSSpushforward}C^{d+\bullet}_{S^1,\mathrm{vir}}(X\operatorname{rel}\partial;A)&\xrightarrow{s_\ast}C_{-\bullet-1}^{S^1}(E;A)
\end{align}
Analogously with \eqref{Epushforward1more}--\eqref{Fpushforward1}, there are natural maps (compatible with \eqref{CSStimesSS}):
\begin{align}
C^\bullet_{S^1,\mathrm{vir}}(-;A)_{IJ}\otimes C_{-\bullet}(E;A'\setminus A)&\to C^\bullet_{S^1,\mathrm{vir}}(-;A')_{I',J'}\\
C^\bullet_{S^1,\mathrm{vir}}(-;A)\otimes C_{-\bullet}(E;A'\setminus A)&\to C^\bullet_{S^1,\mathrm{vir}}(-;A')
\end{align}
\end{definition}

\subsection{Isomorphisms \texorpdfstring{$H^\bullet_{S^1,\mathrm{vir}}(X;A)=\check H^\bullet(X/S^1;\pi_\ast\mathfrak o_X)$}{H\_S{\textasciicircum}1,vir(X;A)=H(X/S{\textasciicircum}1,pi o\_X)} (also \texorpdfstring{$\operatorname{rel}\partial$}{rel d})}

\begin{lemma}[$C^\bullet_{S^1,\mathrm{vir}}(-;A)_{IJ}$ are pure homotopy $\mathcal K$-sheaves]\label{CSTpureSS}
Let $X$ be an almost free $S^1$-space with finite locally $S^1$-orientable $S^1$-equivariant implicit atlas with boundary $A$.  Then $C^\bullet_{S^1,\mathrm{vir}}(-;A)_{IJ}$ and $C^\bullet_{S^1,\mathrm{vir}}(-\operatorname{rel}\partial;A)_{IJ}$ are pure homotopy $\mathcal K$-sheaves on $X/S^1$.  Furthermore, there are canonical isomorphisms of sheaves on $X/S^1$:
\begin{align}
H^0_{S^1,\mathrm{vir}}(-;A)_{IJ}&=\pi_\ast j_!j^\ast\mathfrak o_X\\
H^0_{S^1,\mathrm{vir}}(-\operatorname{rel}\partial;A)_{IJ}&=\pi_\ast j_!j^\ast\mathfrak o_{X\operatorname{rel}\partial}
\end{align}
where $j:V_I\cap V_J\hookrightarrow X$ for $V_I:=\psi_{\varnothing I}((s_I|X_I^\mathrm{reg})^{-1}(0))\subseteq X$ and $\pi:X\to X/S^1$.
\end{lemma}

\begin{proof}
As in the proof of Lemma \ref{CSTpure}, we use Lemmas \ref{singularchainshomotopyKsheaf} and \ref{associatedgradedhomotopysheaf} to see that $C^\bullet_{S^1,\mathrm{vir}}(-;A)_{IJ}$ and $C^\bullet_{S^1,\mathrm{vir}}(-\operatorname{rel}\partial;A)_{IJ}$ are homotopy $\mathcal K$-sheaves.  More precisely, in the present context we need the statement of Lemma \ref{singularchainshomotopyKsheaf} for $C_\bullet^{S^1}$ in place of $C_\bullet$.  The proof of this lemma applies equally well to $C_\bullet^{S^1}$, noting that since $C_\bullet^{S^1}$ is a model of $S^1$-equivariant chains, it in particular satisfies Mayer--Vietoris in that following (total complex) is acyclic:
\begin{equation}
C_\bullet^{S^1}(U\cap U')\to C_\bullet^{S^1}(U)\oplus C_\bullet^{S^1}(U')\to C_\bullet^{S^1}(U\cup U')
\end{equation}

The objects of the new MF-set are $\{M_i\}_{i\in\mathcal Y}\sqcup\{M_i\times[0,1]\}_{i\in\mathcal Y}$, where $M_i\times[0,1]$ is stratified by the following strata:
\begin{align}
M_i^\mathfrak s\times\{0\}&\quad\mathfrak s\in\mathcal S_i\\
M_i^\mathfrak s\times(0,1)&\quad\mathfrak s\in\mathcal S_i\\
M_i^\mathfrak t\times\{1\}&\quad\mathfrak t\in\mathcal F(T_i)
\end{align}
Thus the poset of strata of $M_i\times[0,1]$ is $\mathcal S_i\sqcup\mathcal S_i\sqcup\mathcal F(T_i)$.  For the face identifications, $M_i\times\{0\}$ is identified tautologically with $M_i$, and each of the closed strata $M_i^{\leq\mathfrak t}\times\{1\}$ ($\mathfrak t\in\mathcal F(T_i)$) is identified with the corresponding $\Delta^n$ (considered as an object of $\{M_i\}_{i\in\mathcal Y}$ via the inclusion $\{\Delta^n\}_{n\geq 0}\to\{M_i\}_{i\in\mathcal Y}$).

Now we have a chain of inclusions $\{\Delta^n\}_{n\geq 0}\hookrightarrow\{M_i\}_{i\in\mathcal Y}\hookrightarrow\{M_i\}_{i\in\mathcal Y}\sqcup\{M_i\times[0,1]\}_{i\in\mathcal Y}$.  Since $\mathcal Y$ is saturated, there in fact exists a map backwards $\{M_i\}_{i\in\mathcal Y}\sqcup\{M_i\times[0,1]\}_{i\in\mathcal Y}\to\{M_i\}_{i\in\mathcal Y}$ (acting identically on $\{M_i\}_{i\in\mathcal Y}$).  Using this map, we obtain a chain map $C_\bullet^\mathcal Y(X)\to C_{\bullet+1}^\mathcal Y(X)$ (precompose chains with the projection $M_i\times[0,1]\to M_i$).  This map is a chain homotopy between the identity map and the composition $C_\bullet^\mathcal Y(X)\to C_\bullet(X)\to C_\bullet^\mathcal Y(X)$, so we are done.
\end{proof}

Equip $S^1$ with its standard PL structure, for which the group operations are PL.

\begin{definition}\label{SSMFdef}
An \emph{$S^1$-MF-set} is an MF-set $\mathcal Y$ along with a principal $S^1$-bundle $(ES^1)_\mathcal Y\to(BS^1)_\mathcal Y$ where $(BS^1)_\mathcal Y$ (and hence also $(ES^1)_\mathcal Y$) is an increasing union of compact polyhedra (we do not require $(ES^1)_\mathcal Y$ to be contractible), and for every $i\in\mathcal Y$, a pullback diagram:
\begin{equation}\label{SSMFstructuremaps}
\begin{tikzcd}
M_i\ar{r}\ar{d}&(ES^1)_\mathcal Y\ar{d}\\
N_i\ar{r}&(BS^1)_\mathcal Y
\end{tikzcd}
\end{equation}
with PL maps where $N_i$ (and hence also $M_i$) is a PL manifold, and where the stratification on $M_i$ is pulled back from $N_i$, such that these diagrams are compatible with the face identifications.  A map of $S^1$-MF-sets $\mathcal Y\to\mathcal Y'$ is said to be injective iff it is injective as a map of sets and the map $(ES^1)_\mathcal Y\to(ES^1)_{\mathcal Y'}$ is injective.

There is a forgetful functor from $S^1$-MF-sets to MF-sets, where we remember $M_i$ (of course, there is another natural forgetful functor remembering $N_i$, though we will never use it).  When speaking of a morphism $\mathcal Y\to\mathcal Y'$ where $\mathcal Y$ is an $S^1$-MF-set and $\mathcal Y'$ is an MF-set, we implicitly apply the forgetful functor to $\mathcal Y$.

The category of $S^1$-MF-sets has a natural symmetric monoidal structure: given $S^1$-MF-sets $\{M_i\}_{i\in\mathcal Y}$ and $\{M_j'\}_{j\in\mathcal Y'}$, we may define their product $\{M_i\times M_j'\}_{(i,j)\in\mathcal Y\times\mathcal Y'}$, which is again an $S^1$-MF-set, via the diagonal $S^1$-action on $M_i\times M_j'$ and $(ES^1)_{\mathcal Y\times\mathcal Y'}:=(ES^1)_\mathcal Y\times(ES^1)_{\mathcal Y'}$ with the diagonal action.  The forgetful functor from $S^1$-MF-sets to MF-sets is clearly a symmetric monoidal functor.  It also makes sense to take the product of an $S^1$-MF-set and an MF-set.

For an $S^1$-MF-set $\mathcal Y$, let $C^{S^1,\mathcal Y}_\bullet(X)$ (for $X$ an $S^1$-space) denote the complex generated by commuting diagrams of $S^1$-equivariant maps:
\begin{equation}\label{SSchaindiagram}
\begin{tikzcd}
M_i\ar{r}\ar{d}&X\times(ES^1)_\mathcal Y\ar{r}\ar{d}&(ES^1)_\mathcal Y\ar{d}\\
N_i\ar{r}&(X\times(ES^1)_\mathcal Y)/S^1\ar{r}&(BS^1)_\mathcal Y
\end{tikzcd}
\end{equation}

Then our map $u:C_0\to M$ satisfies:
\begin{equation}\label{pseudoholoncylinderformorseHamiltonian}
\frac{\partial u}{\partial t}+J\circ\frac{\partial u}{\partial s}=\nabla H
\end{equation}
Certainly $u:C_0\to M$ is not constant; otherwise it would be unstable (infinite automorphism group).  Thus $du$ is nonzero somewhere.  If $du$ has rank two somewhere, then we are done.  Thus let us suppose that this is not the case and show that $u|C_0$ is independent of the $t$ coordinate (and thus is a Morse flow line).  Thus there exists some open set $U\subseteq C_0=S^1\times\mathbb R$ where $du$ has rank $1$.  Inside $U$, we have $\ker du\subseteq TC_0=T(S^1\times\mathbb R)$ is an (integrable!) $1$-dimensional distribution, so $U$ is equipped with a $1$-dimensional foliation and $u$ is constant on the leaves.  Thus we have (locally) a factorization $u:S^1\times\mathbb R\xrightarrow r(-\epsilon,\epsilon)\xrightarrow wM$, the leaves of the foliation being given by $r^{-1}(\delta)$ for $\delta\in(-\epsilon,\epsilon)$.  Now \eqref{pseudoholoncylinderformorseHamiltonian} becomes:
\begin{equation}
\Bigl(\frac{\partial r}{\partial t}+\frac{\partial r}{\partial s}\cdot J\Bigr)\cdot w'(r(s,t))=(\nabla H)(w(r(s,t)))
\end{equation}
Since $du$ has rank $1$, we know that $w'(r(s,t))\ne 0$.  Hence the value of $r(s,t)$ determines the value of its derivative uniquely, i.e.\ $dr$ is constant along the leaves $r^{-1}(\delta)$ of the foliation.  It follows that the foliation is (locally) linear(!) and that we can follow any leaf infinitely in both directions and it never exits $U$ (since $dr=0$ outside $U$).  Now if any leaf had nonzero slope, it would force $u:C_0\to M$ to be constant, a contradiction.  Thus all leaves have slope zero; in other words $u$ is independent of the $S^1$-coordinate over $U=S^1\times U'$.  But now we see that $U'=\mathbb R$, since if $U'$ had boundary, it would imply that we have a Morse flow line reaching a critical point in finite time.  Thus $u$ is (globally) a Morse flow line.
\end{proof}

\subsection{Calculation of Hamiltonian Floer homology and the Arnold conjecture}

Arnold conjectured that the minimal number of fixed points of a non-degenerate Hamiltonian symplectomorphism $M\to M$ enjoys a lower bound similar to the minimal number of critical points of a Morse function on $M$ (known as the Morse number of $M$).  It remains an open problem to obtain a sharp bound on the minimal number of symplectic fixed points, though much progress has been made.

Arnold's conjecture was proved for surfaces by Eliashberg \cite{eliashbergsurfaces} and for tori by Conley--Zehnder \cite{conleyzehnder}.  The existence of at least one fixed point was shown by Gromov \cite[p331, 2.3$B_4'$]{gromov} under the assumption $\omega|_{\pi_2(M)}=0$.

A major breakthrough was made by Floer \cite{floersfhs}, who introduced Hamiltonian Floer homology and showed (under some assumptions) that it is isomorphic to singular homology.  Floer's work provides a lower bound on the number of symplectic fixed points of the type predicted by Arnold.  Indeed, if Hamiltonian Floer homology can be defined and shown to be isomorphic to singular homology, then we get a lower bound towards the Arnold conjecture of the form:
\begin{equation}\label{mingenerators}
\min\left\{\operatorname{rk} D_\bullet\,\middle|\,(D_\bullet,d)\;\begin{matrix}\text{a free differential graded $\Lambda$-module}\hfill\cr\text{homotopy equivalent to }C_\bullet(M;\Lambda)\hfill\end{matrix}\right\}
\end{equation}
where $\Lambda$ is the Novikov ring:
\begin{equation}
\Lambda:=\mathbb Z[\operatorname{im}(\pi_2(M)\xrightarrow{\omega\oplus 2c_1(M)}\mathbb R\oplus\mathbb Z)]^\wedge
\end{equation}

A \emph{sheaf} is a presheaf $\mathcal F$ satisfying the following condition:
\begin{equation*}
\tag{Sh}\label{opensheafproperty}0\to\mathcal F\Bigl(\bigcup_{\alpha\in A}U_\alpha\Bigr)\to\prod_{\alpha\in A}\mathcal F(U_\alpha)\to\prod_{\alpha,\beta\in A}\mathcal F(U_\alpha\cap U_\beta)\quad\text{ is exact }\forall\text{ }\{U_\alpha\subseteq X\}_{\alpha\in A}
\end{equation*}
The category of sheaves on a space $X$ is denoted $\operatorname{Shv} X$ (a full subcategory of $\operatorname{Prshv} X$, meaning a morphism between sheaves is the same as a morphism of the corresponding presheaves).
\end{definition}

\begin{definition}[$\mathcal K$-sheaf]
A \emph{$\mathcal K$-sheaf} is a $\mathcal K$-presheaf $\mathcal F$ satisfying the following three conditions:\footnote{A similar set of axioms appears in Lurie \cite[Definition 7.3.4.1]{luriehtt}.}
\begin{align*}
\tag{Sh$_\mathcal K$1}\label{sheafvanishing}\mathcal F(\varnothing)&=0\\
\tag{Sh$_\mathcal K$2}\label{sheafproperty}0\to\mathcal F(K_1\cup K_2)\to\mathcal F(K_1)\oplus\mathcal F(K_2)\to\mathcal F(K_1\cap K_2)&\text{ is exact }\forall\text{ }K_1,K_2\subseteq X\\
\tag{Sh$_\mathcal K$3}\label{sheafcontinuity}\varinjlim_{\begin{smallmatrix}K\subseteq U\cr U\textrm{ open}\end{smallmatrix}}\mathcal F(\overline U)\to\mathcal F(K)&\text{ is an isomorphism }\forall\text{ }K\subseteq X
\end{align*}
The category of $\mathcal K$-sheaves on a space $X$ is denoted $\operatorname{Shv}_\mathcal K X$ (a full subcategory of $\operatorname{Prshv}_\mathcal K X$).
\end{definition}

\begin{remark}\label{nbhdintersectiongood}
It is always the case that $K=\bigcap_{\begin{smallmatrix}K\subseteq U\cr U\textrm{ open}\end{smallmatrix}}\overline U$ for compact $K\subseteq X$.
\end{remark}

\begin{definition}\label{opencptrelationfunctors}
We define functors:
\begin{equation}
\begin{tikzcd}\operatorname{Prshv}_\mathcal K X\ar[yshift=0.5ex]{r}{\alpha_\ast}&\ar[yshift=-0.5ex]{l}{\alpha^\ast}\operatorname{Prshv} X\end{tikzcd}
\end{equation}
by the formulas:
\begin{align}
\label{alphaast}(\alpha^\ast\mathcal F)(K)&:=\varinjlim_{\begin{smallmatrix}K\subseteq U\cr U\textrm{ open}\end{smallmatrix}}\mathcal F(U)\\
\label{alphaupperast}(\alpha_\ast\mathcal F)(U)&:=\varprojlim_{\begin{smallmatrix}K\subseteq U\cr K\textrm{ compact}\end{smallmatrix}}\mathcal F(K)
\end{align}

We have:
\begin{equation}
\begin{tikzcd}\operatorname{Shv}_\mathcal K X\ar[yshift=0.5ex]{r}{\alpha_\ast}&\ar[yshift=-0.5ex]{l}{\alpha^\ast}\operatorname{Shv} X\end{tikzcd}
\end{equation}
and this is an equivalence of categories.\footnote{A similar result appears in Lurie \cite[Corollary 7.3.4.10]{luriehtt}.}
\end{lemma}

\begin{proof}
Suppose $\mathcal F$ is a sheaf, and let us verify $\alpha^\ast\mathcal F$ is a $\mathcal K$-sheaf.  Axiom \eqref{sheafvanishing} is clear (take $A=\varnothing$ in \eqref{opensheafproperty}).  Axiom \eqref{sheafproperty} follows from \eqref{opensheafproperty} and Lemma \ref{intersectioncofinal} since direct limits are exact.  Axiom \eqref{sheafcontinuity} is clear from the definition also.

Suppose $\mathcal F$ is a $\mathcal K$-sheaf, and let us verify that $\alpha_\ast\mathcal F$ is a sheaf.  Let us first observe that (by induction using \eqref{sheafvanishing} and \eqref{sheafproperty}) if $\{K_\alpha\subseteq X\}_{\alpha\in A}$ is any collection of compact sets, all but finitely many of which are empty, then the following is exact:
\begin{equation}\label{compactfiniteexact}
0\to\mathcal F\Bigl(\bigcup_{\alpha\in A}K_\alpha\Bigr)\to\prod_{\alpha\in A}\mathcal F(K_\alpha)\to\prod_{\alpha,\beta\in A}\mathcal F(K_\alpha\cap K_\beta)
\end{equation}
Let us now verify axiom \eqref{opensheafproperty} for $\alpha_\ast\mathcal F$ for open sets $\{U_\alpha\subseteq X\}_{\alpha\in A}$.  Certainly \eqref{opensheafproperty} is the inverse limit of \eqref{compactfiniteexact} over all collections of compact subsets $\{K_\alpha\subseteq U_\alpha\}_{\alpha\in A}$ for which $K_\alpha=\varnothing$ except for finitely many $\alpha\in A$.  This is sufficient since inverse limit is left exact.

Now to see that the adjoint pair $\alpha^\ast\dashv\alpha_\ast$ is actually an equivalence of categories, it suffices to show that the natural morphisms $\mathcal F\to\alpha_\ast\alpha^\ast\mathcal F$ and $\alpha^\ast\alpha_\ast\mathcal G\to\mathcal G$ are isomorphisms.  In other words, we must show that following natural maps are isomorphisms:
\begin{align}
\label{Funit}\mathcal F(U)&\to\varprojlim_{\begin{smallmatrix}K\subseteq U\cr K\textrm{ compact}\end{smallmatrix}}\varinjlim_{\begin{smallmatrix}K\subseteq U'\cr U'\textrm{ open}\end{smallmatrix}}\mathcal F(U')\\
\label{Gunit}\varinjlim_{\begin{smallmatrix}K\subseteq U\cr U\textrm{ open}\end{smallmatrix}}\varprojlim_{\begin{smallmatrix}K'\subseteq U\cr K'\textrm{ compact}\end{smallmatrix}}\mathcal G(K')&\to\mathcal G(K)
\end{align}
The right hand side of \eqref{Funit} can be thought of as the inverse limit of $\mathcal F(U')$ over all open $U'\subseteq U$ with $\overline{U'}\subseteq U$ and $\overline{U'}$ compact.  It is easy to see that the map from $\mathcal F(U)$ to this inverse limit is an isomorphism if $\mathcal F$ is a sheaf.  The left hand side of \eqref{Gunit} can be identified with the left hand side of \eqref{sheafcontinuity}, and thus the map to $\mathcal G(K)$ is an isomorphism if $\mathcal F$ is a $\mathcal K$-sheaf.
\end{proof}

\begin{convention}
In view of the canonical equivalence of categories $\operatorname{Shv} X=\operatorname{Shv}_\mathcal K X$ from Lemma \ref{opencptshvequivalence}, we use the single word ``sheaf'' for an object of either category.
\end{convention}

\begin{lemma}\label{anycompactintersectionworksSH}
Let $\{K_\alpha\}_{\alpha\in A}$ be a filtered directed system of compact subsets of $X$ (i.e.\ for all $\alpha,\beta\in A$ there exists $\gamma\in A$ with $K_\gamma\subseteq K_\alpha\cap K_\beta$).  Then for any $\mathcal F$ satisfying \eqref{sheafcontinuity}, the following is an isomorphism:
\begin{equation}
\varinjlim_{\alpha\in A}\mathcal F(K_\alpha)\to\mathcal F\Bigl(\bigcap_{\alpha\in A}K_\alpha\Bigr)
\end{equation}
\end{lemma}

\begin{proof}
Write $K:=\bigcap_{\alpha\in A}K_\alpha$.  Now consider the diagram:
\begin{equation}
\begin{tikzcd}
\varinjlim\limits_{\alpha\in A}\varinjlim\limits_{\begin{smallmatrix}K_\alpha\subseteq U\cr U\textrm{ open}\end{smallmatrix}}\mathcal F(\overline U)\ar{r}\ar{d}&
\varinjlim\limits_{\begin{smallmatrix}\exists\alpha\in A:K_\alpha\subseteq U\cr U\textrm{ open}\end{smallmatrix}}\mathcal F(\overline U)\ar{r}&
\varinjlim\limits_{\begin{smallmatrix}K\subseteq U\cr U\textrm{ open}\end{smallmatrix}}\mathcal F(\overline U)\ar{d}\\
\varinjlim\limits_{\alpha\in A}\mathcal F(K_\alpha)\ar{rr}&&\mathcal F(K)
\end{tikzcd}
\end{equation}

A \emph{homotopy sheaf} is a complex of presheaves $\mathcal F^\bullet$ satisfying the following condition:
\begin{equation*}
\tag{hSh}\label{openhomotopysheafproperty}\hspace{-20pt}\biggl[\mathcal F^\bullet\Bigl(\bigcup_{\alpha\in A}U_\alpha\Bigr)\to\prod_{\alpha\in A}\mathcal F^{\bullet-1}(U_\alpha)\to\prod_{\alpha,\beta\in A}\mathcal F^{\bullet-2}(U_\alpha\cap U_\beta)\to\cdots\biggr]\text{ is acyclic }\forall\text{ }\{U_\alpha\subseteq X\}_{\alpha\in A}
\end{equation*}
The category of homotopy sheaves on a space $X$ is denoted $\operatorname{hShv} X$ (morphisms are morphisms of complexes of presheaves).
\end{definition}

\begin{remark}
The definition above is given for illustrative purposes only.  It is probably only a good definition for $\mathcal F^\bullet$ which is bounded below, and it would perhaps be better to impose \eqref{openhomotopysheafproperty} for all \emph{hypercovers} of open subsets $U\subseteq X$.
\end{remark}

\begin{example}\label{flasquehomotopysheafresolution}
A sheaf $\mathcal F$ is \emph{flasque} iff all restriction maps $\mathcal F(U)\to\mathcal F(U')$ are surjective.  It is easy to see that any bounded below complex of flasque sheaves $\mathcal F^\bullet$ is a homotopy sheaf.  For example, let $\mathcal F^\bullet(U):=C^\bullet(U)$ be the presheaf of singular cochain complexes.  Then the sheafification of $\mathcal F^\bullet$ is a complex of flasque sheaves, and thus is a homotopy sheaf.  One can show (using barycentric subdivision) that the map from $\mathcal F^\bullet$ to its sheafification is a quasi-isomorphism, and hence $\mathcal F^\bullet$ is a homotopy sheaf as well.
\end{example}

\begin{definition}[Homotopy $\mathcal K$-sheaf]\label{homotopyKsheaf}
A \emph{homotopy $\mathcal K$-sheaf} is a complex of $\mathcal K$-presheaves $\mathcal F^\bullet$ satisfying the following three conditions:
\begin{align*}
\tag{hSh$_\mathcal K$1}\label{homotopysheafacyclic}\mathcal F^\bullet(\varnothing)&\text{ is acyclic}\\
\tag{hSh$_\mathcal K$2}\label{homotopysheafproperty}\hspace{-10pt}\bigl[\mathcal F^\bullet(K_1\cup K_2)\to\mathcal F^{\bullet-1}(K_1)\oplus\mathcal F^{\bullet-1}(K_2)\to\mathcal F^{\bullet-2}(K_1\cap K_2)\bigr]&\text{ is acyclic }\forall\text{ }K_1,K_2\subseteq X\\
\tag{hSh$_\mathcal K$3}\label{homotopysheafcontinuity}\smash{\varinjlim_{\begin{smallmatrix}K\subseteq U\cr U\textrm{ open}\end{smallmatrix}}}\mathcal F^\bullet(\overline U)\to\mathcal F^\bullet(K)&\text{ is a quasi-isomorphism }\forall\text{ }K\subseteq X
\end{align*}

Then $\mathfrak o_M$ is locally isomorphic to the constant sheaf $\underline\mathbb Z$, and there is a sequence of sheaves which is exact on stalks:
\begin{equation}
0\to\mathfrak o_{M\operatorname{rel}\partial}\to\mathfrak o_M\to i_\ast\mathfrak o_{\partial M}\to 0
\end{equation}
where $i:\partial M\hookrightarrow M$, and the second map comes from the boundary map in the long exact sequence of the pair $(M,\partial M)$.
\end{definition}

\begin{lemma}[Homotopy $\mathcal K$-sheaf axioms for singular chains]\label{singularchainshomotopyKsheaf}
Let $X$ be a topological space.  Then we have:
\begin{rlist}
\item\label{scacyc}$C_\bullet(X,X)$ is acyclic.
\item\label{scpatch}Let $A,B\subseteq X$ be closed.  Then the complex:
\begin{equation*}
\bigl[C_\bullet(X,X\setminus(A\cup B))\to C_{\bullet+1}(X,X\setminus A)\oplus C_{\bullet+1}(X,X\setminus B)\to C_{\bullet+2}(X,X\setminus(A\cap B))\bigr]
\end{equation*}
is acyclic.
\item\label{sccont}Let $K=\bigcap_{\alpha\in A}K_\alpha$ where $\{K_\alpha\}_{\alpha\in A}$ is a family of closed subsets of $X$ which is \emph{filtered} in the sense that for all $\alpha_1,\alpha_2\in A$, there exists $\beta\in A$ with $K_\beta\subseteq K_{\alpha_1}\cap K_{\alpha_2}$.  Then $\varinjlim_{\alpha\in A}C_\bullet(X,X\setminus K_\alpha)\to C_\bullet(X,X\setminus K)$ is a quasi-isomorphism.
\end{rlist}
\end{lemma}

\begin{proof}
Statement (\ref{scacyc}) is obvious.

Statement (\ref{scpatch}) can be deduced from Mayer--Vietoris using a form of the nine lemma as we now explain.  Let us write $U:=X\setminus A$ and $V:=X\setminus B$.  Now consider the following total complex:
\begin{equation}
\begin{CD}
C_\bullet(U\cap V)@>>>C_{\bullet+1}(U)\oplus C_{\bullet+1}(V)@>>>C_{\bullet+2}(U\cup V)\cr
@VVV@VVV@VVV\cr
C_{\bullet+1}(X)@>>>C_{\bullet+2}(X)\oplus C_{\bullet+2}(X)@>>>C_{\bullet+3}(X)\cr
@VVV@VVV@VVV\cr
C_{\bullet+2}(X,U\cap V)@>>>C_{\bullet+3}(X,U)\oplus C_{\bullet+3}(X,V)@>>>C_{\bullet+4}(X,U\cup V)\cr
\end{CD}
\end{equation}

}  Then there is a canonical isomorphism:
\begin{equation}\label{poincaredualitygoal}
H^\bullet[C_{n-1-\bullet}(N,N\setminus X)\to C_{n-\bullet}(M,M\setminus X)]=\check H^\bullet_c(X;i^\ast j_!j^\ast\mathfrak o_M)
\end{equation}
where $j:M^\circ\cup N^\circ\hookrightarrow M$.  In particular, specializing to $N=\varnothing$, there is a canonical isomorphism:
\begin{equation}
H_{n-\bullet}(M,M\setminus X)=\check H^\bullet_c(X;i^\ast\mathfrak o_{M\operatorname{rel}\partial M})
\end{equation}
\end{lemma}

\begin{proof}
Let $X^+$ be the one-point compactification of $X$.  Define a complex of $\mathcal K$-presheaves $\mathcal F^\bullet$ on $X^+$:
\begin{equation}\label{purehomotopyKsheafinPD}
\mathcal F^\bullet(K):=[C_{n-1-\bullet}(N,N\setminus K)\to C_{n-\bullet}(M,M\setminus K)]
\end{equation}

Now, it is easy to calculate:
\begin{equation}\label{stalkhomologyofPDpure}
H^\bullet\mathcal F^\bullet_p=\begin{cases}\mathbb Z&p\in M^\circ\cup N^\circ\cr 0&p\notin M^\circ\cup N^\circ\end{cases}
\end{equation}
concentrated in degree zero (see \cite[p231 \S3.3]{hatcher} for the special case $N=\partial M=\varnothing$).  Hence $\mathcal F^\bullet$ is a pure homotopy $\mathcal K$-sheaf.  In fact, it is not hard to see (using the adjunction $j_!\dashv j^\ast$) that \eqref{stalkhomologyofPDpure} lifts to an isomorphism of sheaves $f_!i^\ast j_!j^\ast\mathfrak o_M\to H^0\mathcal F^\bullet$ where $f:X\hookrightarrow X^+$.

Now we conclude:
\begin{equation*}
H^\bullet\mathcal F^\bullet(X^+)\overset{\text{Prop \ref{cechcohomologypurehomotopysheaf}}}=\check H^\bullet(X^+;f_!i^\ast j_!j^\ast\mathfrak o_M)\overset{\text{Lem \ref{cptcechembeddingproperty}}}=\check H^\bullet_c(X;i^\ast j_!j^\ast\mathfrak o_M)
\end{equation*}
Now observe that $H^\bullet\mathcal F^\bullet(X^+)$ is the left hand side of \eqref{poincaredualitygoal}.
\end{proof}

\begin{remark}[Why homotopy $\mathcal K$-sheaves instead of homotopy sheaves?]
The naive modification of \eqref{purehomotopyKsheafinPD} substituting open $U\subseteq X$ in place of compact $K\subseteq X$ does not yield a homotopy sheaf.  To get a homotopy sheaf, one could apply the proposed functor $R\alpha_\ast:\operatorname{hShv}_\mathcal K X\to\operatorname{hShv} X$ from Remark \ref{homotopyKnotsheavesequivalencermk} to the homotopy $\mathcal K$-sheaf \eqref{purehomotopyKsheafinPD}.  It is somewhat easier, though, to just work directly in the setting of homotopy $\mathcal K$-sheaves (which has some advantages, for example stalks of $\mathcal K$-presheaves are easier to define/understand).  It is for this reason that throughout this paper we work with homotopy $\mathcal K$-sheaves instead of homotopy sheaves.
\end{remark}

\subsection{Homotopy colimits}\label{hocolimintro}

We make common use of the following type of ``homotopy diagram'' and its corresponding ``homotopy colimit''.  

\begin{definition}[Homotopy diagram]
Let $\mathcal S$ be a finite poset.  A \emph{homotopy diagram over $\mathcal S$} is a collection of complexes $\{A^\bullet_{\mathfrak s,\mathfrak t}\}_{\mathfrak s\preceq\mathfrak t\in\mathcal S}$ equipped with compatible maps $A^\bullet_{\mathfrak s,\mathfrak t}\to A^\bullet_{\mathfrak s',\mathfrak t'}$ for $\mathfrak s\preceq\mathfrak s'\preceq\mathfrak t'\preceq\mathfrak t$ (meaning that $A^\bullet_{\mathfrak s,\mathfrak t}\to A^\bullet_{\mathfrak s',\mathfrak t'}\to A^\bullet_{\mathfrak s'',\mathfrak t''}$ and $A^\bullet_{\mathfrak s,\mathfrak t}\to A^\bullet_{\mathfrak s'',\mathfrak t''}$ agree).
\end{definition}

\begin{definition}[Homotopy colimit]\label{homotopycolimit}
Let $\mathcal S$ be a finite poset and let $\{A^\bullet_{\mathfrak s,\mathfrak t}\}_{\mathfrak s\preceq\mathfrak t\in\mathcal S}$ be a homotopy diagram over $\mathcal S$.  We define the \emph{homotopy colimit}:
\begin{equation}
\operatornamewithlimits{hocolim}_{\mathfrak s\preceq\mathfrak t\in\mathcal S}A^\bullet_{\mathfrak s,\mathfrak t}:=\bigoplus_{p\geq 0}\bigoplus_{\mathfrak s_0\prec\cdots\prec\mathfrak s_p\in\mathcal S}A^{\bullet+p}_{\mathfrak s_0,\mathfrak s_p}
\end{equation}

Now there is a natural morphism:
\begin{equation}\label{tensorproductdirectlimitmorphism}
\operatornamewithlimits{hocolim}_{\mathfrak s\preceq\mathfrak s'\in\mathcal S}A^\bullet_{\mathfrak s,\mathfrak s'}\otimes\operatornamewithlimits{hocolim}_{\mathfrak t\preceq\mathfrak t'\in\mathcal T}B^\bullet_{\mathfrak t,\mathfrak t'}\to\operatornamewithlimits{hocolim}_{\mathfrak s\times\mathfrak t\preceq\mathfrak s'\times\mathfrak t'\in\mathcal S\times\mathcal T}A^\bullet_{\mathfrak s,\mathfrak s'}\otimes B^\bullet_{\mathfrak t,\mathfrak t'}
\end{equation}
To define this morphism, we simply observe that the nerve of $\mathcal S\times\mathcal T$ is the standard simplicial subdivision of the product of the nerves of $\mathcal S$ and $\mathcal T$, and this is covered by a morphism of coefficient systems.\footnote{In fact, from this perspective one easily sees that \eqref{tensorproductdirectlimitmorphism} is always a quasi-isomorphism.}
\end{definition}

\subsection{Homotopy colimits of pure homotopy \texorpdfstring{$\mathcal K$}{K}-sheaves}\label{cechsimplegluingsection}

We introduce a gluing construction for pure homotopy $\mathcal K$-sheaves.  The relevance of this Lemma \ref{gluingcechsimple} is best understood in its (only) intended application, namely Lemma \ref{Cpure} (which is best understood in context).

\begin{lemma}[$\operatornamewithlimits{hocolim}$ preserves homotopy $\mathcal K$-sheaves]\label{pihomotopysheaf}
Let $\mathcal S$ be a finite poset and let $\{\mathcal F^\bullet_{\mathfrak s,\mathfrak t}\}_{\mathfrak s\preceq\mathfrak t\in\mathcal S}$ be a homotopy diagram of homotopy $\mathcal K$-sheaves.  Then $\operatornamewithlimits{hocolim}_{\mathfrak s\preceq\mathfrak t\in\mathcal S}\mathcal F^\bullet_{\mathfrak s,\mathfrak t}$ is a homotopy $\mathcal K$-sheaf.
\end{lemma}

\begin{proof}
The associated graded of the $p$-filtration on $\operatornamewithlimits{hocolim}_{\mathfrak s\preceq\mathfrak t\in\mathcal S}\mathcal F^\bullet_{\mathfrak s,\mathfrak t}$ is a homotopy $\mathcal K$-sheaf by assumption; now use Lemma \ref{associatedgradedhomotopysheaf}.
\end{proof}

\begin{lemma}[Gluing pure homotopy $\mathcal K$-sheaves]\label{gluingcechsimple}
Let $A$ be a finite set.  Let $\{U_I\}_{I\subseteq A}$ be an open cover of a space $X$ satisfying:
\begin{rlist}
\item\label{nestedintersectionOK}$U_I\cap U_K\subseteq U_J$ for $I\subseteq J\subseteq K$.
\item\label{nonnestedintersectionbig}$U_I\cap U_{I'}\subseteq U_{I\cup I'}$ for $I,I'\subseteq A$.
\end{rlist}
Let $\mathcal G$ be a sheaf on $X$ and let $\mathcal G_{IJ}:=(j_{IJ})_!(j_{IJ})^\ast\mathcal G$ where $j_{IJ}:U_I\cap U_J\hookrightarrow X$.  By property (\ref{nestedintersectionOK}), this gives rise to a homotopy diagram $\{\mathcal G_{IJ}\}_{I\subseteq A}$ over $2^A$ of sheaves on $X$.

Let $\{\mathcal F_{IJ}^\bullet\}_{I\subseteq J\subseteq A}$ be a homotopy diagram over $2^A$ of pure homotopy $\mathcal K$-sheaves on $X$, and suppose we give a compatible system of isomorphisms $\mathcal G_{IJ}\xrightarrow\sim H^0\mathcal F^\bullet_{IJ}$.  Then $\mathcal F^\bullet:=\operatornamewithlimits{hocolim}_{I\subseteq J\subseteq A}\mathcal F^\bullet_{IJ}$ is a pure homotopy $\mathcal K$-sheaf and there is a canonical induced isomorphism $\mathcal G\xrightarrow\sim H^0\mathcal F^\bullet$.
\end{lemma}

\begin{proof}
Certainly $\mathcal F^\bullet$ is a homotopy $\mathcal K$-sheaf by Lemma \ref{pihomotopysheaf}.  Since $A$ is finite, it is easy to see that $H^i\mathcal F^\bullet_{IJ}$ being bounded below implies that $H^i\mathcal F^\bullet$ is bounded below.

Now let us calculate $\mathcal F^\bullet_p$ using the spectral sequence associated to the $p$-filtration.  The $E_1$ term is concentrated along the $q=0$ row since $(H^q\mathcal F^\bullet_{IJ})_p$ is concentrated in degree zero; thus there are no further differentials after the $E_1$ page.  On the $E_1$ page the differentials coincide precisely with the differentials in the definition of $\operatornamewithlimits{hocolim}_{I\subseteq J\subseteq A}(\mathcal G_{IJ})_p$ (regarding $\mathcal G_{IJ}$ as complexes concentrated in degree zero).  Hence we have an isomorphism:
\begin{equation}\label{FGiso}
H^\bullet\mathcal F^\bullet_p=H^\bullet\operatornamewithlimits{hocolim}_{I\subseteq J\subseteq A}(\mathcal G_{IJ})_p
\end{equation}

We define:
\begin{equation}\label{cechcomplexIIderived}
\check C^\bullet(X;\mathcal F^\bullet):=\varinjlim_{\begin{smallmatrix}\{U_x\subseteq X\}_{x\in X}\cr\text{rigid open cover}\end{smallmatrix}}\bigoplus_{p\geq 0}\prod_{\begin{smallmatrix}S\subseteq X\cr\left|S\right|=p+1\end{smallmatrix}}\mathcal F^{\bullet-p}\Bigl(\bigcap_{x\in S}\overline{U_x}\Bigr)
\end{equation}

We define:
\begin{equation}
\mathop{R\varprojlim}_{\lambda\in\Lambda}C^\bullet_\lambda:=\prod_{q\geq 0}\prod_{\lambda_0\leq\ldots\leq\lambda_q}C^{\bullet-q}_{\lambda_0}
\end{equation}

We define:
\begin{equation}\label{limidef}
\mathop{\textstyle\varprojlim^i}\limits_{\lambda\in\Lambda}A_\lambda:=H^i\Bigl[\mathop{R\varprojlim}_{\lambda\in\Lambda}A_\lambda\Bigr]
\end{equation}

Then the following natural map is an isomorphism:
\begin{equation}
\mathop{\textstyle\varprojlim^i}\limits_{\lambda\in\Lambda}A_\lambda\xrightarrow\sim\mathop{\textstyle\varprojlim^i}\limits_{\lambda'\in\Lambda'}A_{f(\lambda')}
\end{equation}
More generally, the following natural map is a quasi-isomorphism:
\begin{equation}
\mathop{R\varprojlim}_{\lambda\in\Lambda}C^\bullet_\lambda\xrightarrow\sim\mathop{R\varprojlim}_{\lambda'\in\Lambda'}C^\bullet_{f(\lambda')}
\end{equation}
\end{lemma}

\begin{proof}
For $\textstyle\varprojlim^i$, see \cite[p291, Theorem 14.9]{mardesic}, and for $\mathop{R\varprojlim}$, see \cite[p349, Corollary 17.18]{mardesic}.
\end{proof}

\begin{lemma}\label{quasiisomorphismforRlim}
If $C_\lambda^\bullet\xrightarrow\sim D_\lambda^\bullet$ is a morphism of inverse systems which is a level-wise quasi-isomorphism (i.e.\ for every $\lambda$), then the natural map:
\begin{equation}
\mathop{R\varprojlim}_{\lambda\in\Lambda}C^\bullet_\lambda\xrightarrow\sim\mathop{R\varprojlim}_{\lambda\in\Lambda}D^\bullet_\lambda
\end{equation}
is a quasi-isomorphism.
\end{lemma}

\begin{proof}
See \cite[p348, Theorem 17.16]{mardesic}.
\end{proof}

\subsubsection{Steenrod chains}

\begin{definition}[due to Chogoshvili \cite{chogoshvili}]
A partition $X=\bigsqcup_{i=1}^nE_i$ shall mean an \emph{unordered} partition into finitely many disjoint nonempty subsets $E_1,\ldots,E_n\subseteq X$; there is an associated finite closed covering $X=\bigcup_{i=1}^n\overline{E_i}$, whose nerve is denoted $N(X;\{\overline{E_i}\}_{i=1}^n)$ (the simplicial complex with vertices $\{1,\ldots,n\}$ where $S\subseteq\{1,\ldots,n\}$ spans a simplex iff $\bigcap_{i\in S}\overline{E_i}\ne\varnothing$).  A partition $\{F_j\}_{j=1}^m$ refines $\{E_i\}_{i=1}^n$ iff for all $j$, there exists a (necessarily unique) $i$ with $F_j\subseteq E_i$.  For a refinement $\{E_i\}_{i=1}^n\to\{F_j\}_{j=1}^m$, there is an associated map of nerves $N(X;\{\overline{F_j}\})\to N(X;\{\overline{E_i}\})$.
\end{definition}

For doing \v Cech theory, Chogoshvili's construction has exceptionally nice properties.  The collection of partitions is a set, and there is at most one morphism between any pair of partitions.  The poset of partitions is cofinite (a given partition refines only finitely many other partitions).  Each nerve $N(X;\{\overline{E_i}\})$ is a finite simplicial complex, and the transition maps $N(X;\{\overline{F_j}\})\to N(X;\{\overline{E_i}\})$ are all surjective.  Also, any pair of partitions has a minimal common refinement.  Given a map $f:X\to Y$, a partition $\{E_i\}$ of $Y$ pulls back to a partition $\{f^{-1}(E_i)\}$ of $X$, and there is an associated map on nerves $N(X;\{\overline{f^{-1}(E_i)}\})\to N(Y,\{\overline{E_i}\})$.

\begin{lemma}\label{inverselimithassamecech}
Let $X$ be compact.  There is a natural map:
\begin{equation}\label{chogoshvilinervecomparison}
\varprojlim_{X=\bigsqcup_{i=1}^nE_i}N(X;\{\overline{E_i}\})\to X
\end{equation}
which induces an isomorphism on \v Cech cohomology.
\end{lemma}

\begin{proof}
There is a natural correspondence $C\subseteq X\times N(X;\{\overline E_i\})$, whose fiber over $x\in X$ is the complete simplex on $\{i:x\in\overline{E_i}\}$.  Now it is not hard to check that the inverse limit of these correspondences maps bijectively (and thus homeomorphically) to $\varprojlim_{X=\bigsqcup_{i=1}^nE_i}N(X;\{\overline{E_i}\})$, thus giving rise to the desired map \eqref{chogoshvilinervecomparison}.

Now the inverse image of $p\in X$ under \eqref{chogoshvilinervecomparison} is an inverse limit of complete simplices with surjective transition maps (``the complete simplex on a profinite set''), and this has the \v Cech cohomology of a point.  Indeed, for any inverse system of compact spaces $\{X_\alpha\}$, the natural map $\varinjlim_\alpha\check H^\bullet(X_\alpha)\to\check H^\bullet(\varprojlim_\alpha X_\alpha)$ is an isomorphism (since open covers of $\varprojlim_\alpha X_\alpha$ pulled back from some $X_\alpha$ are cofinal among all open covers).  Thus it follows from the Leray spectral sequence that \eqref{chogoshvilinervecomparison} induces an isomorphism on \v Cech cohomology.
\end{proof}

\begin{definition}[Steenrod chains and homology]\label{steenrodhomdef}
Let $X$ be compact.  We define:
\begin{equation}\label{steenrodchainsRlimeqn}
\overline C_\bullet(X):=\mathop{R\varprojlim}_{X=\bigsqcup_{i=1}^nE_i}\bigoplus_{p\geq 0}\bigoplus_{\begin{smallmatrix}S\subseteq\{1,\ldots,n\}\cr\left|S\right|=p+1\cr\bigcap_{i\in S}\overline{E_i}\ne\varnothing\end{smallmatrix}}\mathbb Z[-p]
\end{equation}

Fix a finite dimensional vector space $E$ and a linear map:
\begin{equation}\label{lambdafix}
\lambda:E\to C^\infty(\overbrace{\overline{\mathcal C}^\circ\underset\overline{\mathcal M}\times\cdots\underset\overline{\mathcal M}\times\overline{\mathcal C}^\circ}^{r\text{ times}}{}\underset\overline{\mathcal M}\times\overline{\mathcal C}^\circ\times X,\Omega^{0,1}_{\overline{\mathcal C}^\circ/\overline{\mathcal M}}\otimes_\mathbb C TX)
\end{equation}
Here $\Omega^{0,1}_{\overline{\mathcal C}^\circ/\overline{\mathcal M}}$ is the $(0,1)$-part of the complexified vertical cotangent bundle $T^\ast_{\overline{\mathcal C}^\circ/\overline{\mathcal M}}\otimes_\mathbb R\mathbb C$ of (the last factor of) $\overline{\mathcal C}^\circ\to\overline{\mathcal M}$, and $C^\infty$ means smooth sections.  We require that $\lambda$ be zero in a neighborhood of the nodes $\overline{\mathcal C}\setminus\overline{\mathcal C}^\circ$ of the last $\overline{\mathcal C}^\circ$ factor.

For a nodal curve $C$, we denote by $\tilde C$ its normalization, i.e.\ the unique smooth compact Riemann surface equipped with a map $\tilde C\to C$ which identifies points in pairs to form the nodes of $C$.  A function on $C$ being smooth means (by definition) that its pullback to $\tilde C$ is smooth.

Fix a homology class $\beta\in H_2(X;\mathbb Z)$.  We are interested in the following moduli space:
\begin{equation}\label{Mbarfirstdef}
\overline{\mathcal M}(X):=\left\{\begin{matrix}s\in\overline{\mathcal M}\hfill\cr u:C_s\to X\hfill\cr x_i\in C_s\quad 1\leq i\leq r\hfill\cr e\in E\hfill\end{matrix}\;\middle|\;\begin{matrix}u\text{ smooth and }u_\ast[C_s]=\beta\hfill\cr u(p_{n+i})\in D^\circ\quad\hfill(1\leq i\leq\ell)\cr u(x_i)\in D_i^\circ\text{ and }u\pitchfork D_i\text{ at }x_i\quad\hfill(1\leq i\leq r)\cr\bar\partial u+\lambda(e)(x_1,\ldots,x_r,\cdot,u(\cdot))=0\hfill\end{matrix}\right\}
\end{equation}

We consider the smooth Banach manifold:
\begin{equation}
\mathcal B:=\Bigl\{(u,e)\in W^{k,p}(C_{s_0},X)\times E\Bigm|u(p_{n+i})\in D^\circ\;(1\leq i\leq\ell)\Bigr\}
\end{equation}

On each side of each node of $C_0$, fix a ``cylindrical end'', that is, a map:
\begin{equation}\label{cylindricalends}
[0,\infty)\times S^1\to C_0
\end{equation}
which is a biholomorphism onto some small neighborhood $D^2\setminus 0$ of the node.  We use coordinates $(s,t)\in[0,\infty)\times S^1$, which is given the standard holomorphic structure $z=e^{s+it}$.

Let $\overline{\mathcal M}^d\subseteq\overline{\mathcal M}$ denote the locus of curves with exactly $d$ nodes.  Pick a smooth family of smooth almost complex structures $j_y$ on $C_0$ parameterized by $y\in\mathbb R^{\dim\overline{\mathcal M}^d}$, where $j_0$ is the given almost complex structure on $C_0$, which is constant over the cylindrical ends \eqref{cylindricalends}, and such that the induced map $\mathbb R^{\dim\overline{\mathcal M}^d}\to\overline{\mathcal M}^d$ is a diffeomorphism onto its image.

Now consider the following procedure, which takes a ``gluing parameter'' $\alpha=e^{-6S+i\theta}\in\mathbb C$ and two copies of the standard end $[0,\infty)\times S^1\sqcup[0,\infty)\times S^1$.  We first truncate both ends, leaving just the subset $[0,6S]\times S^1\sqcup[0,6S]\times S^1$.  We then identify $(s,t)$ in the first piece with $(6S-s,\theta-t)=(s',t')$ in the second piece.  We call the resulting cylinder a ``neck''.

Now given gluing parameters\footnote{In the present construction, and in many other constructions/definitions to come later, certain expressions, equalities, etc. only make sense or only hold if the gluing parameters $\alpha_i\in\mathbb C$ are sufficiently close to zero (i.e.\ $\left|\alpha_i\right|\leq\epsilon$ for some $\epsilon>0$ depending only on data which we have previously fixed).  We will often leave this assumption implicit, since we only care about what happens for $\alpha$ in a neighborhood of $0\in\mathbb C^d$ anyway.  The same goes for $y\in\mathbb R^{\dim\overline{\mathcal M}^d}$.} $\alpha=(\alpha_1,\ldots,\alpha_d)\in\mathbb C^d$, we may perform the gluing operation above on $C_0$, using the chosen cylindrical ends \eqref{cylindricalends}.  We call the resulting curve $C_\alpha$, and it is equipped with cylindrical ends (corresponding to those $\alpha_i=0$) and necks (corresponding to those $\alpha_i\ne 0$):
\begin{align}
\label{Gend}[0,\infty)\times S^1\to C_\alpha\\
\label{Gneck}[0,6S_i]\times S^1\to C_\alpha
\end{align}
In each neck, we have coordinates $(s,t)\in[0,6S_i]\times S^1$ and coordinates $(s',t')\in[0,6S_i]\times S^1$, which satisfy $s+s'=6S_i$ and $t+t'=\theta_i$.  The curve $C_\alpha$ is also equipped with $n+\ell$ marked points $p_1,\ldots,p_{n+\ell}\in C_\alpha$ coming from the given $p_1,\ldots,p_{n+\ell}\in C_0$.  Since $j_y$ is constant over the cylindrical ends, it descends to give an almost complex structure on $C_\alpha$.

Now since $\overline{\mathcal M}\to\overline{\mathcal M}_{g,n+\ell}$ is \'etale, there is an induced map:
\begin{align}
\mathbb C^d\times\mathbb R^{\dim\overline{\mathcal M}^d}&\to\overline{\mathcal M}\\
(\alpha,y)&\mapsto(C_\alpha,j_y,p_1,\ldots,p_{n+\ell})
\end{align}
which is a local diffeomorphism near zero.  Using these local coordinates, we may alternatively define $\overline{\mathcal M}(X)$ as:
\begin{equation}\label{modulispace}
\overline{\mathcal M}(X):=\left\{\begin{matrix}\alpha\in\mathbb C^d\hfill\cr y\in\mathbb R^{\dim\overline{\mathcal M}^d}\hfill\cr u:C_\alpha\to X\hfill\cr x_i\in C_\alpha\quad 1\leq i\leq r\hfill\cr e\in E\hfill\end{matrix}\;\middle|\;\begin{matrix}u\text{ smooth and }u_\ast[C_\alpha]=\beta\hfill\cr u(p_{n+i})\in D^\circ\quad\hfill(1\leq i\leq\ell)\cr u(x_i)\in D_i^\circ\text{ and }u\pitchfork D_i\text{ at }x_i\quad\hfill(1\leq i\leq r)\cr\bar\partial_yu+\lambda(e)(\alpha,y,x_1,\ldots,x_r,\cdot,u(\cdot))=0\hfill\end{matrix}\right\}
\end{equation}

For the purposes of \eqref{modulispace}, $\lambda$ denotes the function:
\begin{equation*}
\lambda:E\to C^\infty(\mathbb C^d\times\mathbb R^{\dim\overline{\mathcal M}^d}\times\overbrace{C_0\times\cdots\times C_0}^{r\text{ times}}{}\times C_0\times X,\operatorname{Hom}_\mathbb R(T\tilde C_0,TX))
\end{equation*}
for which $\lambda(\cdot)(\cdot,y,\ldots)$ lands in $\Omega^{0,1}_{\tilde C_0,j_y}\otimes_\mathbb C TX\subseteq\operatorname{Hom}_\mathbb R(T\tilde C_0,TX)$, defined in terms of the old $\lambda$ via:
\begin{multline*}
\lambda^\mathrm{new}(e)(\alpha,y,x_1,\ldots,x_r,p,x):=\\
\lambda^\mathrm{old}(e)(x_1\in(C_\alpha,j_y)\subseteq\overline{\mathcal C},\ldots,x_r\in (C_\alpha,j_y)\subseteq\overline{\mathcal C},p\in(C_\alpha,j_y)\subseteq\overline{\mathcal C},x)
\end{multline*}

Now to prove the main result, it suffices to study the local structure of $\overline{\mathcal M}(X)$ (defined as in \eqref{modulispace}) near the basepoint:
\begin{equation}
(0,0,u_0:C_0\to X,\{x_i^0\},e_0)
\end{equation}
which we are assuming lies in $\overline{\mathcal M}(X)^\mathrm{reg}$.

\subsection{Pregluing}

Let $\exp:TX\to X$ denote the exponential map of some Riemannian metric on $X$ for which $D$ is totally geodesic.  Let $\nabla$ denote any $J$-linear\footnote{Given any connection $\nabla^0$, the connection $\nabla_XY:=\frac 12(\nabla^0_XY-J(\nabla^0_X(JY)))$ is $J$-linear.} connection on $TX$ (equivalently, a connection for which $\nabla J=0$).  Let $\mathsf{PT}_{x\to y}:T_xX\to T_yX$ denote parallel transport via $\nabla$ along the shortest geodesic between $x$ and $y$ (we will only use this notation when it may be assumed that $x$ and $y$ are very close in $X$); note that $\mathsf{PT}_{x\to y}$ is $J$-linear.

Fix a smooth function $\chi:\mathbb R\to[0,1]$ satisfying:
\begin{equation}
\chi(x)=\begin{cases}0&x\leq 0\cr 1&x\geq 1\end{cases}
\end{equation}

Over an end $[0,\infty)\times S^1$, we define it as follows:
\begin{equation}
u_{0|\alpha}(s,t):=\begin{cases}
u_0(s,t)&s\leq S-1\cr
\exp_{u_0(n)}\left[\chi(S-s)\cdot\exp_{u_0(n)}^{-1}u_0(s,t)\right]&S-1\leq s\leq S\cr
u_0(n)&S\leq s
\end{cases}
\end{equation}

Over a neck $[0,6S]\times S^1$, we define it as follows:
\begin{equation}
u_\alpha(s,t):=\begin{cases}
u_0(s,t)&s\leq S-1\cr
\exp_{u_0(n)}\left[\chi(S-s)\cdot\exp_{u_0(n)}^{-1}u_0(s,t)\right]&S-1\leq s\leq S\cr
u_0(n)&S\leq s\leq 5S\cr
\exp_{u_0(n)}\left[\chi(S-s')\cdot\exp_{u_0(n)}^{-1}u_0(s',t')\right]&5S\leq s\leq 5S+1\cr
u_0(s',t')&5S+1\leq s
\end{cases}
\end{equation}

For $\xi\in C^\infty(C_0,u_0^\ast TX)$, we define:
\begin{equation}
\xi_\alpha\in C^\infty(C_\alpha,u_\alpha^\ast TX)
\end{equation}
as follows.  Away from the necks, $\xi_\alpha$ coincides with $\xi$.  Over a neck $[0,6S]\times S^1$, we define it as follows:
\begin{equation}\label{kernelpregluingformula}
\xi_\alpha(s,t):=\begin{cases}
\xi(s,t)&s\leq S-1\cr
\mathsf{PT}_{u_0(s,t)\to u_\alpha(s,t)}\left[\xi(s,t)\right]&S-1\leq s\leq S\cr
\mathsf{PT}_{u_0(s,t)\to u_\alpha(s,t)}\left[\xi(s,t)\right]\cdot(1-\chi(s-S))+\chi(s-S)\cdot \xi(n)&S\leq s\leq S+1\cr
\xi(n)&S+1\leq s\leq 5S-1\cr
\mathsf{PT}_{u_0(s',t')\to u_\alpha(s',t')}\left[\xi(s',t')\right]\cdot(1-\chi(s'-S))+\chi(s'-S)\cdot \xi(n)&5S-1\leq s\leq 5S\cr
\mathsf{PT}_{u_0(s',t')\to u_\alpha(s',t')}\left[\xi(s',t')\right]&5S\leq s\leq 5S+1\cr
\xi(s',t')&5S+1\leq s
\end{cases}
\end{equation}

To make calculations in ends/necks easier, for each node $n\in C_0$ we fix the local trivialization of $TX$ given by parallel transport:
\begin{equation}\label{localPTcoords}
\mathsf{PT}_{u_0(n)\to p}:T_{u_0(n)}X\to T_pX
\end{equation}
over $p$ contained in a small ball centered at $u_0(n)$.  We assume that the ends \eqref{cylindricalends} were chosen small enough so that $u_0$ maps each end into a compact subset of the small ball associated to the corresponding node.

\begin{definition}
For $\alpha\in\mathbb C^d$, we define a weighted Sobolev space:
\begin{equation}
W^{k,2,\delta}(C_0,u_{0|\alpha}^\ast TX)
\end{equation}
using the following norm.  We use the usual $(k,2)$ norm away from the ends.  Over an end $[0,\infty)\times S^1\subseteq C_0$, we consider the local trivialization \eqref{localPTcoords}, in which a section of $u_{0|\alpha}^\ast TX$ simply becomes a function $\xi:[0,\infty)\times S^1\to T_{u_0(n)}X$.  In terms of this function, the contribution from the end to the norm squared is:
\begin{equation}\label{endnorm}
\left|\xi(n)\right|^2+\int_{[0,\infty)\times S^1}\biggl[\left|\xi(s,t)-\xi(n)\right|^2+\sum_{j=1}^k\left|D^j\xi(s,t)\right|^2\biggr]e^{2\delta s}\;ds\,dt
\end{equation}
The derivatives of $\xi$ are measured with respect to the standard metric on $[0,\infty)\times S^1$.

By Sobolev embedding $W^{2,2}\hookrightarrow C^0$ in two dimensions, in any end we have a uniform bound on $\left|\xi(s,t)-\xi(n)\right|e^{\delta s}$ and $\left|D^j\xi(s,t)\right|e^{\delta s}$ ($1\leq j\leq k-2$) linear in $\left\|\xi\right\|_{k,2,\delta}$.
\end{definition}

\begin{definition}
For $\alpha\in\mathbb C^d$, we define a weighted Sobolev space:
\begin{equation}
W^{k,2,\delta}(C_\alpha,u_\alpha^\ast TX)
\end{equation}
using the following norm.  We use the usual $(k,2)$ norm away from the ends/necks.  Over an end, the contribution to the norm squared is \eqref{endnorm}.  Over a neck $[0,6S]\times S^1\subseteq C_\alpha$, we again think of a section as a function $\xi:[0,6S]\times S^1\to T_{u_0(n)}X$, and the contribution to the norm squared is:
\begin{equation*}
\biggl|\int_{S^1}\xi(3S,t)\,dt\biggr|^2+\int_{[0,6S]\times S^1}\biggl[\Bigl|\xi(s,t)-\int_{S^1}\xi(3S,t)\,dt\Bigr|^2+\sum_{j=1}^k\left|D^j\xi(s,t)\right|^2\biggr]e^{2\delta\min(s,6S-s)}\;ds\,dt
\end{equation*}
Of course, for fixed $\alpha\in\mathbb C^d$, this norm is equivalent to not weighting the necks, though the two norms are not uniformly equivalent as $\alpha\to 0$.  The weight in the necks is important since the key point is to establish certain estimates which are uniform as $\alpha\to 0$.

By Sobolev embedding $W^{2,2}\hookrightarrow C^0$ in two dimensions, in any neck we have a uniform bound on $\left|\xi(s,t)-\int_{S^1}\xi(3S,t)\,dt\right|e^{\delta\min(s,6S-s)}$ and $\left|D^j\xi(s,t)\right|e^{\delta\min(s,6S-s)}$ ($1\leq j\leq k-2$) linear in $\left\|\xi\right\|_{k,2,\delta}$.
\end{definition}

\begin{definition}
For $\alpha\in\mathbb C^d$, we define a weighted Sobolev space:
\begin{equation}
W^{k-1,2,\delta}(\tilde C_\alpha,\Omega^{0,1}_{\tilde C_\alpha,j_y}\otimes_\mathbb C u_\alpha^\ast TX)
\end{equation}
as follows.  We use the usual $(k-1,2)$ norm away from the ends/necks.  Over an end or neck, we trivialize $(T\tilde C_\alpha,j_y)$ over $\mathbb C$ by the basis vector $\frac\partial{\partial s}$, and we trivialize $TX$ via \eqref{localPTcoords}, and hence the section is simply a function $\eta$ from the end/neck to $T_{u_0(n)}X$.  In terms of this function, the contribution to the norm squared is (for end/neck respectively):
\begin{align}
\int_{[0,\infty)\times S^1}&\sum_{j=0}^{k-1}\left|D^j\eta(s,t)\right|^2e^{2\delta s}\;ds\,dt\\
\int_{[0,6S]\times S^1}&\sum_{j=0}^{k-1}\left|D^j\eta(s,t)\right|^2e^{2\delta\min(s,6S-s)}\;ds\,dt
\end{align}
By Sobolev embedding $W^{2,2}\hookrightarrow C^0$ in two dimensions, in any end (resp.\ neck) we have a uniform bound on $\left|D^j\eta(s,t)\right|e^{\delta s}$ (resp.\ $\left|D^j\eta(s,t)\right|e^{\delta\min(s,6S-s)}$) ($1\leq j\leq k-3$) linear in $\left\|\eta\right\|_{k,2,\delta}$.
\end{definition}

\subsection{Based \texorpdfstring{$\bar\partial$-section}{del bar section} \texorpdfstring{$\mathcal F_{\alpha,y}$}{F\_alpha,y} and linearized operator \texorpdfstring{$D_{\alpha,y}$}{D\_alpha,y}}

Fix a norm on $E$.  On direct sums of normed spaces we use the direct sum norm $\left\|a\oplus b\right\|:=\left\|a\right\|+\left\|b\right\|$.

We consider the following partially defined function:
\begin{gather*}
\mathcal F_{\alpha,y}:C^\infty(C_\alpha,u_\alpha^\ast TX)_D\oplus E\to C^\infty(\tilde C_\alpha,\Omega^{0,1}_{\tilde C_\alpha,j_y}\otimes_\mathbb C u_\alpha^\ast TX)\\
\xi\mapsto\mathsf{PT}_{\exp_{u_\alpha}\xi\to u_\alpha}\left[\bar\partial_y\exp_{u_\alpha}\xi+\lambda(e_0+\operatorname{proj}_E\xi)(\alpha,y,x_1,\ldots,x_r,\cdot,(\exp_{u_\alpha}\xi)(\cdot))\right]
\end{gather*}

Now we observe that $\mathcal F_{\alpha,y}$ extends continuously to a map:
\begin{equation}
\mathcal F_{\alpha,y}:W^{k,2,\delta}(C_\alpha,u_\alpha^\ast TX)_D\oplus E\to W^{k-1,2,\delta}(\tilde C_\alpha,\Omega^{0,1}_{\tilde C_\alpha,j_y}\otimes_\mathbb C u_\alpha^\ast TX)
\end{equation}
which is defined for $\left\|\xi\right\|_{k,2,\delta}\leq c'$ (some $c'>0$).  Moreover, this map is highly differentiable (see \eqref{intersectionsfunction}--\eqref{firstdelbarsection} and the surrounding discussion; recall we have fixed $k\geq 6$).  We denote by:
\begin{equation}
D_{\alpha,y}:W^{k,2,\delta}(C_\alpha,u_\alpha^\ast TX)_D\oplus E\to W^{k-1,2,\delta}(\tilde C_\alpha,\Omega^{0,1}_{\tilde C_\alpha,j_y}\otimes_\mathbb C u_\alpha^\ast TX)
\end{equation}
the derivative of $\mathcal F_{\alpha,y}$ at zero.

Let $T_\nabla(X,Y):=\nabla_XY-\nabla_YX-[X,Y]$ denote the torsion of $\nabla$.  Let $(\cdot)^{0,1}_y$ denote the projection $\operatorname{Hom}_\mathbb R(T\tilde C_\alpha,u_\alpha^\ast TX)\to\Omega^{0,1}_{\tilde C_\alpha,j_y}\otimes_\mathbb C u_\alpha^\ast TX$, so $(V)^{0,1}_y:=\frac 12(V+J\circ V\circ j_y)$.

\begin{lemma}\label{linearizedformula}
The linearized operator $D_{\alpha,y}$ is given by:
\begin{align}\label{formulaforlinearizedoperator}
D_{\alpha,y}\xi&=\Bigl(\nabla\xi+T_\nabla(\xi,du_\alpha)\Bigr)^{0,1}_y\cr
&\quad+\sum_{i=1}^r\frac{d[\lambda(e_0)]}{dx_i}(\alpha,y,x_1,\ldots,x_r,\cdot,u_\alpha(\cdot))(-\operatorname{proj}_{TC_\alpha}\xi(x_i))\cr
&\quad+\nabla_\xi[\lambda(e_0)](\alpha,y,x_1,\ldots,x_r,\cdot,u_\alpha(\cdot))\cr
&\quad+\lambda(\operatorname{proj}_E\xi)(\alpha,y,x_1,\ldots,x_r,\cdot,u_\alpha(\cdot))
\end{align}

We have:
\begin{equation}
\left\|\bar\partial_yu_\alpha+\lambda(e_0)(\alpha,y,x_1^0,\ldots,x_r^0,\cdot,u_\alpha(\cdot))\right\|_{k-1,2,\delta}\leq c\cdot\left[\left|y\right|+\sum_{i=1}^de^{-(1-\delta)S_i}\right]
\end{equation}
uniformly over $(\alpha,y)$ in a neighborhood of zero, for $c<\infty$ depending on data which has been previously fixed.
\end{lemma}

Data which has been previously fixed includes $(s_0,u_0,\{x_i^0\},e_0)$, the cylindrical ends, $j_y$, the metrics used to define $\exp$ and Sobolev norms, $k$, $\delta$, the cutoff function $\chi$, the norms on $E$, $K$, $\mathbb C^d$, $\mathbb R^{\dim\overline{\mathcal M}^d}$, etc.

\begin{proof}
Away from the ends/necks of $C_\alpha$, the expression is zero when $y=0$ (since $(0,0,u_0,\{x_i^0\},e_0)\in\overline{\mathcal M}(X)$) and more generally it follows easily that its $j$th derivative is bounded pointwise by $c_j\left|y\right|$.  In the ends of $C_\alpha$, the expression is zero.

In a given neck $[0,6S]\times S^1\subseteq C_\alpha$, argue as follows.  Recall that $\lambda$ vanishes in the ends/necks, so we just have to bound $\bar\partial_yu_\alpha$.  Now $\bar\partial_yu_\alpha$ is only nonzero over $[S-1,S]\cup[5S,5S+1]$; by symmetry we may just work over $[S-1,S]$.  Now since $u_0$ is smooth, it and all its derivatives decay exponentially in any cylindrical end $[0,\infty)\times S^1$ (since every end is holomorphically conjugate to the map $[0,\infty)\times S^1\to D^2$ given by $z=e^{-s-it}$).  Precisely, we have the following pointwise bound over $[S-1,S]$:
\begin{equation}\label{uzeroexponentialdecay}
\left|D^ju_0(s,t)\right|\leq c_je^{-S}
\end{equation}
(derivatives with respect to $s$ and $t$).  It follows from the definition of $u_\alpha$ that the same bound holds for $u_\alpha$.  Thus the contribution of $[S-1,S]$ to the norm of $\bar\partial_yu_\alpha$ is bounded by a constant times $e^{S\delta}e^{-S}$.
\end{proof}

\begin{lemma}[Estimate for kernel pregluing]\label{pregluingKestimate}
For all $\kappa\in K$, we have:
\begin{equation}
\left\|D_{\alpha,y}\kappa_\alpha\right\|_{k-1,2,\delta}\leq c\cdot\left[\left|y\right|+\sum_{i=1}^de^{-(1-\delta)S_i}\right]\left\|\kappa\right\|
\end{equation}
uniformly over $(\alpha,y)$ in a neighborhood of zero, for $c<\infty$ depending on data which has been previously fixed.
\end{lemma}

\begin{proof}
Away from the ends/necks, the norm is bounded by $c\cdot\left|y\right|\left\|\kappa\right\|$.  In the ends, the expression is zero.  In the necks, argue as follows.

The expression is only nonzero over $[S-1,S+1]\cup[5S-1,5S+1]$; by symmetry we may just work over $[S-1,S+1]$.  Then since $u_0$ and $\kappa$ are smooth, we have (by the same reasoning used to justify \eqref{uzeroexponentialdecay}) the following pointwise bound over $[S-1,S+1]$:
\begin{equation}
\left|D^j\kappa_\alpha(s,t)\right|\leq c_je^{-S}\left\|\kappa\right\|
\end{equation}
(derivatives with respect to $s$ and $t$, in local coordinates \eqref{localPTcoords}).  Thus the overall contribution of $[S-1,S+1]$ to the total norm of the expression is bounded by a constant times $e^{S\delta}e^{-S}\left\|\kappa\right\|$.
\end{proof}

\subsection{Approximate right inverse}

Recall that by assumption, the linearized operator:
\begin{equation}
D_{0,0}:W^{k,2,\delta}(C_0,u_0^\ast TX)_D\oplus E\to W^{k-1,2,\delta}(\tilde C_0,\Omega^{0,1}_{\tilde C_0,j_0}\otimes_\mathbb C u_0^\ast TX)
\end{equation}
is surjective (even if we replace $E$ with $E'$).  We now proceed to fix a bounded right inverse:
\begin{equation}\label{chosenrightinverse}
Q_{0,0}:W^{k-1,2,\delta}(\tilde C_0,\Omega^{0,1}_{\tilde C_0,j_0}\otimes_\mathbb C u_0^\ast TX)\to W^{k,2,\delta}(C_0,u_0^\ast TX)_D\oplus E'
\end{equation}
whose image admits a simple description (the description of the image will be important for the proof that the gluing map is continuous (Proposition \ref{continuityofgluing})).  Fix a collection of points $q_i\in C_0$ ($1\leq i\leq h$) not contained in any of the cylindrical ends, subspaces $V_i\subseteq T_{u_0(q_i)}X$, and a subspace $E''\subseteq E'$ so that the natural evaluation map:
\begin{equation}
L_0:K\xrightarrow\sim\biggl(\bigoplus_{i=1}^hT_{u_0(q_i)}X/V_i\biggr)\oplus E/E''
\end{equation}
is an isomorphism (such choices exist since $K\twoheadrightarrow E/E'$ is surjective and elements of $K$ satisfy unique continuation).  Now we can consider the same evaluation map on the larger space:
\begin{equation}\label{lineartofixinverse}
L_0:W^{k,2,\delta}(C_0,u_0^\ast TX)_D\oplus E\to W:=\biggl(\bigoplus_{i=1}^hT_{u_0(q_i)}X/V_i\biggr)\oplus E/E''
\end{equation}

We define the map:
\begin{equation}
W^{k,2,\delta}(C_0,u_{0|\alpha}^\ast TX)_D\xrightarrow{\mathrm{glue}}W^{k,2,\delta}(C_\alpha,u_\alpha^\ast TX)_D
\end{equation}
Let $\xi\in W^{k,2,\delta}(C_0,u_{0|\alpha}^\ast TX)_D$.  Away from the necks of $C_\alpha$, $\operatorname{glue}(\xi)$ is simply $\xi$.  In any particular neck $[0,6S]\times S^1\subseteq C_\alpha$, we define:
\begin{equation}
\operatorname{glue}(\xi)(s,t):=\begin{cases}
\xi(s,t)&s\leq 2S\cr
\xi(n)+\chi(4S-s)\cdot[\xi(s,t)-\xi(n)]+\chi(4S-s')\cdot[\xi(s',t')-\xi(n)]&2S\leq s\leq 4S\cr
\xi(s',t')&4S\leq s
\end{cases}
\end{equation}

Let us make the elementary observation that the definition of $L_0$ extends perfectly well to give an analogous bounded linear map:
\begin{equation}\label{newLonpreglued}
L_\alpha:W^{k,2,\delta}(C_\alpha,u_\alpha^\ast TX)_D\oplus E\to W
\end{equation}
Since $\operatorname{im} Q_{0,0}\subseteq\ker L_0$, it follows from the definition of $T_{\alpha,y}$ that $\operatorname{im} T_{\alpha,y}\subseteq\ker L_\alpha$ as well.  This is a key ingredient in the proof that the gluing map is continuous (Proposition \ref{continuityofgluing}).

\begin{lemma}\label{approxbottom}
Let:
\begin{equation}
\begin{CD}
X@>D>>Y\cr
@AGAA@VVBV\cr
X'@>D'>>Y'
\end{CD}
\end{equation}
denote the bottom square in \eqref{biginversediagram}.  Then for $\xi\in X'$ and $\eta\in Y$ with $D'\xi=B\eta$, we have:
\begin{equation}
\left\|DG\xi-\eta\right\|\leq c\cdot\left\|\xi\right\|\left|y\right|
\end{equation}
uniformly over $(\alpha,y)$ in a neighborhood of zero, for $c<\infty$ depending on data which has been previously fixed.
\end{lemma}

\begin{proof}
In simpler terms, we have $\left\|D_{0,y}-I_y\circ D_{0,0}\right\|\leq c\cdot\left|y\right|$ (calculation left to the reader) and this trivially implies the claimed statement.
\end{proof}

\begin{lemma}\label{approxmiddle}
Let:
\begin{equation}
\begin{CD}
X@>D>>Y\cr
@AGAA@VVBV\cr
X'@>D'>>Y'
\end{CD}
\end{equation}
denote the middle square in \eqref{biginversediagram}.  Then for $\xi\in X'$ and $\eta\in Y$ with $D'\xi=B\eta$, we have:
\begin{equation}
\left\|DG\xi-\eta\right\|\leq c\cdot\left\|\xi\right\|\sum_{i=1}^de^{-S_i}
\end{equation}
uniformly over $(\alpha,y)$ in a neighborhood of zero, for $c<\infty$ depending on data which has been previously fixed.
\end{lemma}

\begin{proof}
In simpler terms, we bound the operator norm of the difference between the two diagonal compositions:
\begin{equation}\label{betterPTcommutingoperatornormbound}
\left\|\mathsf{PT}\circ D_{0,y}-D_{0|\alpha,y}\circ\mathsf{PT}\right\|\leq c\cdot\sum_{i=1}^de^{-S_i}
\end{equation}
(this trivially implies the claimed statement).  To show \eqref{betterPTcommutingoperatornormbound}, observe that the two operators only differ over the $[S-1,\infty)$ subset of each end $[0,\infty)\times S^1\subseteq C_0$.  Using estimates \eqref{uzeroexponentialdecay} arising from the fact that $u_0$ is smooth, we obtain the desired bound.
\end{proof}

\begin{lemma}\label{approxtop}
Let:
\begin{equation}
\begin{CD}
X@>D>>Y\cr
@AGAA@VVBV\cr
X'@>D'>>Y'
\end{CD}
\end{equation}
denote the top square in \eqref{biginversediagram}.  Then for $\xi\in X'$ and $\eta\in Y$ with $D'\xi=B\eta$, we have:
\begin{equation}
\left\|DG\xi-\eta\right\|\leq c\cdot\left\|\xi\right\|\sum_{i=1}^de^{-2\delta S_i}
\end{equation}
uniformly over $(\alpha,y)$ in a neighborhood of zero, for $c<\infty$ depending on data which has been previously fixed.
\end{lemma}

\begin{proof}
The difference $DG\xi-\eta$ is only nonzero in the necks over $s\in[2S,2S+1]$ and $s\in[4S-1,4S]$.  By symmetry, we may just do the bound over $s\in[4S-1,4S]$.  Over this region, one calculates that the norm of the difference is bounded as claimed.  The factor of $e^{-2\delta S}$ comes as the ratio between the $e^{2\delta S}$ weight given to $[4S-1,4S]\times S^1\subseteq[0,6S]\times S^1\subseteq C_\alpha$ and the $e^{4\delta S}$ weight given to $[4S-1,4S]\times S^1\subseteq[0,\infty)\times S^1\subseteq C_0$.
\end{proof}

\begin{lemma}\label{bootstrapinverse}
Let $X$ and $Y$ be Banach spaces, let $D:X\to Y$ and $T:Y\to X$ be bounded, and suppose $\epsilon:=\left\|DT-\mathbf 1_Y\right\|<1$.  Then:
\begin{equation}
Q:=T\cdot\sum_{n\geq 0}(\mathbf 1_Y-DT)^n
\end{equation}

In addition, we have the following estimates:
\begin{equation}
\left\|Q\right\|\leq\frac 1{1-\epsilon}\left\|T\right\|\qquad
\left\|Q-T\right\|\leq\frac\epsilon{1-\epsilon}\left\|T\right\|
\end{equation}
\end{lemma}

\begin{proof}
Use the telescoping sum $(\mathbf 1-A)\sum_{n\geq 0}A^n=\mathbf 1$ for $\left\|A\right\|<1$.
\end{proof}

\begin{lemma}\label{bootstrappingapprox}
Suppose we have a diagram of Banach spaces as follows:
\begin{equation}
\begin{tikzcd}
X_1\ar{r}{D_1}&Y_1\ar{d}{B_1}\\
\vdots\ar{u}{G_1}&\vdots\ar{d}{B_{n-2}}\\
X_{n-1}\ar{u}{G_{n-2}}\ar{r}{D_{n-1}}&Y_{n-1}\ar{d}{B_{n-1}}\\
X_n\ar{u}{G_{n-1}}\ar[yshift=0.5ex]{r}{D_n}&Y_n\ar[yshift=-0.5ex]{l}{Q_n}
\end{tikzcd}
\end{equation}
where $\left\|D_i\right\|,\left\|G_i\right\|,\left\|B_i\right\|,\left\|Q_n\right\|\leq c$ and $D_nQ_n=\mathbf 1$.  Then for all $\delta>0$ there exists $\epsilon=\epsilon(n,c,\delta)>0$ such that if for all $1<i\leq n$:
\begin{equation}\label{keytocheckforARI}
D_i\xi=B_{i-1}\eta\implies\left\|D_{i-1}G_{i-1}\xi-\eta\right\|\leq\epsilon\cdot\left\|\xi\right\|
\end{equation}
then we have:
\begin{equation}\label{approxbootstrappingworks}
\left\|D_1G_1\cdots G_{n-1}Q_nB_{n-1}\cdots B_1-\mathbf 1_{Y_1}\right\|\leq\delta
\end{equation}
\end{lemma}

\begin{proof}
We work by induction on $n$.  The case $n=1$ is clear: $\epsilon(1,c,\delta)=\infty$.

Now assume $n\geq 2$.  Let us also assume without loss of generality that $c\geq 1$.  Applying \eqref{keytocheckforARI} to $i=n$ and $\xi=Q_nB_{n-1}\eta$, we see that:
\begin{equation}
\left\|D_{n-1}G_{n-1}Q_nB_{n-1}-\mathbf 1_{Y_{n-1}}\right\|\leq\epsilon\cdot\left\|Q_n\right\|\left\|B_{n-1}\right\|\leq\epsilon c^2
\end{equation}
Let us require that $\epsilon\leq\frac 12c^{-2}$, so the above bound is $\leq\frac 12$.  Then by Lemma \ref{bootstrapinverse} applied to $T=G_{n-1}Q_nB_{n-1}$, we see that there exists $Q_{n-1}$ with $D_{n-1}Q_{n-1}=\mathbf 1_{Y_{n-1}}$ and:
\begin{equation}
\left\|Q_{n-1}\right\|\leq 2c^3\qquad\left\|Q_{n-1}-G_{n-1}Q_nB_{n-1}\right\|\leq 2\epsilon c^5
\end{equation}
Now we see that:
\begin{multline}\label{approxclosetogiven}
\left\|D_1G_1\cdots G_{n-2}G_{n-1}Q_nB_{n-1}B_{n-2}\cdots B_1-D_1G_1\cdots G_{n-2}Q_{n-1}B_{n-2}\cdots B_1\right\|\\
\leq c^{2n-3}\left\|G_{n-1}Q_nB_{n-1}-Q_{n-1}\right\|\leq 2\epsilon c^{2n+2}
\end{multline}
Let us require that $\epsilon\leq\frac 14\delta c^{-2n-2}$, so the above bound is $\leq\frac 12\delta$.  Let us also require that $\epsilon\leq\epsilon(n-1,2c^3,\frac 12\delta)$ (which exists by the induction hypothesis), so that:
\begin{equation}\label{inductionbound}
\left\|D_1G_1\cdots G_{n-2}Q_{n-1}B_{n-2}\cdots B_1-\mathbf 1_{Y_1}\right\|\leq\frac 12\delta
\end{equation}
Combining \eqref{approxclosetogiven} and \eqref{inductionbound}, we get the desired bound \eqref{approxbootstrappingworks}.
\end{proof}

\begin{proposition}[Approximate right inverse $T_{\alpha,y}$]\label{approxworks}
We have:
\begin{align}
\left\|T_{\alpha,y}\right\|&\leq c\\
\label{Tapproxeqn}\left\|D_{\alpha,y} T_{\alpha,y}-\mathbf 1\right\|&\to 0\\
\operatorname{im} T_{\alpha,y}&\subseteq\ker L_\alpha
\end{align}
as $(\alpha,y)\to 0$, for $c<\infty$ depending on data which has been previously fixed.
\end{proposition}

\begin{proof}
It is easy to see that all the maps in \eqref{biginversediagram} are uniformly bounded.  Hence $\left\|T_{\alpha,y}\right\|\leq c$ as $(\alpha,y)\to 0$.  Now Lemma \ref{bootstrappingapprox} combined with Lemmas \ref{approxbottom}, \ref{approxmiddle}, \ref{approxtop} show that for $(\alpha,y)\to 0$, we have $\left\|D_{\alpha,y} T_{\alpha,y}-\mathbf 1\right\|\to 0$.  We observed earlier that $\operatorname{im} T_{\alpha,y}\subseteq\ker L_\alpha$.
\end{proof}

\begin{definition}[Right inverse $Q_{\alpha,y}$]
We define a map:
\begin{equation}
Q_{\alpha,y}:W^{k-1,2,\delta}(\tilde C_\alpha,\Omega^{0,1}_{\tilde C_\alpha,j_y}\otimes_\mathbb C u_\alpha^\ast TX)\to W^{k,2,\delta}(C_\alpha,u_\alpha^\ast TX)_D\oplus E
\end{equation}
as the sum:
\begin{equation}
Q_{\alpha,y}:=T_{\alpha,y}\sum_{k=0}^\infty(\mathbf 1-D_{\alpha,y} T_{\alpha,y})^k
\end{equation}

We have:
\begin{align}
\left\|Q_{\alpha,y}\right\|&\leq c\\
D_{\alpha,y}Q_{\alpha,y}&=\mathbf 1\\
\operatorname{im} Q_{\alpha,y}&\subseteq\ker L_\alpha
\end{align}
uniformly over $(\alpha,y)$ in a neighborhood of zero, for $c<\infty$ depending on data which has been previously fixed.
\end{proposition}

\begin{proof}
Apply Lemma \ref{bootstrapinverse} and Proposition \ref{approxworks}.
\end{proof}

\subsection{Quadratic estimates}

\begin{proposition}[Quadratic estimate]\label{quadestimate}
There exist $c'>0$ and $c<\infty$ (depending on data which has been previously fixed) such that for $\left\|\xi_1\right\|_{k,2,\delta},\left\|\xi_2\right\|_{k,2,\delta}\leq c'$, we have:
\begin{equation}\label{quadestgoal}
\bigl\|D_{\alpha,y}(\xi_1-\xi_2)-(\mathcal F_{\alpha,y}\xi_1-\mathcal F_{\alpha,y}\xi_2)\bigr\|_{k-1,2,\delta}\leq c\cdot\left\|\xi_1-\xi_2\right\|_{k,2,\delta}(\left\|\xi_1\right\|_{k,2,\delta}+\left\|\xi_2\right\|_{k,2,\delta})
\end{equation}
(and $\mathcal F_{\alpha,y}\xi_1$ and $\mathcal F_{\alpha,y}\xi_2$ are both defined), uniformly over $(\alpha,y)$ in a neighborhood of zero.
\end{proposition}

\begin{proof}
This is similar to McDuff--Salamon \cite[p68, Proposition 3.5.3]{mcduffsalamonJholsymp}.

We have already remarked that $\mathcal F_{\alpha,y}\xi$ is defined for $\left\|\xi\right\|_{k,2,\delta}\leq c'$.

Let $\mathcal F_{\alpha,y}'(\zeta,\xi)$ denote the derivative of $\mathcal F_{\alpha,y}$ at $\zeta$ applied to $\xi$.  So, for instance, $D_{\alpha,y}(\xi):=\mathcal F_{\alpha,y}'(0,\xi)$.  It suffices to show that:
\begin{equation}\label{derivislip}
\left\|\mathcal F_{\alpha,y}'(0,\xi)-\mathcal F_{\alpha,y}'(\zeta,\xi)\right\|_{k-1,2,\delta}\leq c\cdot\left\|\zeta\right\|_{k,2,\delta}\left\|\xi\right\|_{k,2,\delta}
\end{equation}

For $\zeta\in W^{k,2,\delta}(C_\alpha,u_\alpha^\ast TX)_D\oplus E$, let:
\begin{equation}
\mathcal F_{\alpha,y,\zeta}:W^{k,2,\delta}(C_\alpha,(\exp_{u_\alpha}\zeta)^\ast TX)_D\oplus E\to W^{k-1,2,\delta}(\tilde C_\alpha,\Omega^{0,1}_{\tilde C_\alpha,j_y}\otimes_\mathbb C(\exp_{u_\alpha}\zeta)^\ast TX)
\end{equation}
denote the $\bar\partial$-section based at $\exp_{u_\alpha}\zeta:C_\alpha\to X$ and $e_0+\operatorname{proj}_E\zeta$ (so, for example, $\mathcal F_{\alpha,y}:=\mathcal F_{\alpha,y,0}$).  Let:
\begin{equation}
D_{\alpha,y,\zeta}:W^{k,2,\delta}(C_\alpha,(\exp_{u_\alpha}\zeta)^\ast TX)_D\oplus E\to W^{k-1,2,\delta}(\tilde C_\alpha,\Omega^{0,1}_{\tilde C_\alpha,j_y}\otimes_\mathbb C(\exp_{u_\alpha}\zeta)^\ast TX)
\end{equation}

By Lemma \ref{contractionprop}, the map $\xi\mapsto\xi-Q_{\alpha,y}\mathcal F_{\alpha,y}\xi$ is a $\frac 12$-contraction mapping when restricted to:
\begin{equation}\label{domainofcontraction}
\{\xi\in\kappa_\alpha+\operatorname{im} Q_{\alpha,y}:\left\|\xi\right\|_{k,2,\delta}\leq c'\}
\end{equation}
To finish the proof, it suffices to show that (for sufficiently small $(\alpha,y,\kappa)$) \eqref{domainofcontraction} is nonempty and is mapped to itself by $\xi\mapsto\xi-Q_{\alpha,y}\mathcal F_{\alpha,y}\xi$.

We know that $\left\|\kappa_\alpha\right\|_{k,2,\delta}\to 0$ as $\kappa\to 0$ (uniformly in $(\alpha,y)$), so \eqref{domainofcontraction} is nonempty.  By using Proposition \ref{quadestimate} with $(\xi_1,\xi_2)=(0,\kappa_\alpha)$ and Lemmas \ref{mappregluingissmall} and \ref{pregluingKestimate}, we conclude that:
\begin{equation}\label{kernelclosetoholomorphic}
\left\|\mathcal F_{\alpha,y}\kappa_\alpha\right\|_{k-1,2,\delta}\to 0
\end{equation}
as $(\alpha,y,\kappa)\to 0$.  Since the operator norm of $Q_{\alpha,y}$ is bounded uniformly as $(\alpha,y)\to 0$, we see that $\kappa_\alpha$ is almost fixed by $\xi\mapsto\xi-Q_{\alpha,y}\mathcal F_{\alpha,y}\xi$ as $(\alpha,y,\kappa)\to 0$.  It then follows from the contraction property that $\xi\mapsto\xi-Q_{\alpha,y}\mathcal F_{\alpha,y}\xi$ maps \eqref{domainofcontraction} to itself.
\end{proof}

\subsection{Gluing}

\begin{definition}[Gluing map]
We define:
\begin{align}
u_{\alpha,y,\kappa}&:=\exp_{u_\alpha}\kappa_{\alpha,y}\\
e_{\alpha,y,\kappa}&:=e_0+\operatorname{proj}_E\kappa_{\alpha,y}
\end{align}

where $f_i:[0,6S_i]\to[0,6S]$ is defined as follows:
\begin{align}
f_i(s):=&\begin{cases}
s&s\leq S-2\cr
s-3S_i+3S&3S_i-2S+2\leq s\leq 3S_i+2S-2\cr
s-6S_i+6S&6S_i-S+2\leq s\cr
\end{cases}\\
f_i([S-2,3S_i-2S+2])&\subseteq[S-2,S+2]\\
f_i([3S_i+2S-2,6S_i-S+2])&\subseteq[5S-2,5S+2]
\end{align}

Now using \eqref{zdzbaridentity}, we see that:
\begin{equation*}
\int_{S^1}\gamma^\ast\lambda_\mathrm{std}=\frac i2\int_{S^1}\sum_j\gamma^\ast(z_j\,d\bar z_j)=\frac i2\int_{S^1}\sum_{k,\ell}a_k\bar a_\ell(-i\ell)e^{i(k-\ell)t}\,dt=\pi\sum_kk\left|a_k\right|^2
\end{equation*}
We may also calculate:
\begin{equation}
\int_{S^1}\Bigl|\frac{d\gamma}{dt}\Bigr|^2\,dt=\int_{S^1}\sum_{k,\ell}a_k\bar a_\ell(ik)(-i\ell)e^{i(k-\ell)t}\,dt=2\pi\sum_kk^2\left|a_k\right|^2
\end{equation}
Hence we conclude that:
\begin{equation}\label{sympisoperimetric}
\left|\int_{S^1}\gamma^\ast\lambda_\mathrm{std}\right|\leq\frac 12\int_{S^1}\Bigl|\frac{d\gamma}{dt}\Bigr|^2\,dt
\end{equation}

Let:
\begin{equation}
E(r):=\int_{[-r,r]\times S^1}\Bigl|\frac{du}{dt}\Bigr|^2\,ds\,dt\approx\int_{[-r,r]\times S^1}u^\ast\omega_\mathrm{std}=\int_{\partial[-r,r]\times S^1}u^\ast\lambda_\mathrm{std}
\end{equation}

Applying \eqref{sympisoperimetric}, we conclude that:
\begin{equation}\label{boundonenergyfromboundary}
E(r)\lesssim\frac 12\int_{\partial[-r,r]\times S^1}\Bigl|\frac{du}{dt}\Bigr|^2\,dt
\end{equation}
($\lesssim$ means inequality up to a factor which can be made arbitrarily close to $1$ by taking $\epsilon>0$ sufficiently small).  The right hand side above equals $\frac 12E'(r)$, so we have $E'(r)\gtrsim 2E(r)$, and hence $E'(r)\geq 2\mu E(r)$ (for $\epsilon>0$ sufficiently small), from which we conclude that $E(r)\leq e^{2\mu\cdot(r-R)}E(R)$.  Using \eqref{boundonenergyfromboundary} to bound $E(R)$, we see that:
\begin{equation}
E(r)\lesssim e^{2\mu\cdot(r-R)}\frac 12\int_{\partial[-R,R]\times S^1}\Bigl|\frac{du}{dt}\Bigr|^2\,dt
\end{equation}
We have:
\begin{equation}
E(r)\approx\frac 12\int_{[-r,r]\times S^1}\biggl[\Bigl|\frac{du}{ds}\Bigr|^2+\Bigl|\frac{du}{dt}\Bigr|^2\biggr]\,ds\,dt
\end{equation}
Hence we conclude that:
\begin{equation}
\int_{[-r,r]\times S^1}\biggl[\Bigl|\frac{du}{ds}\Bigr|^2+\Bigl|\frac{du}{dt}\Bigr|^2\biggr]\,ds\,dt\lesssim e^{ 2\mu\cdot(r-R)}\int_{\partial[-R,R]\times S^1}\Bigl|\frac{du}{dt}\Bigr|^2\,dt
\end{equation}
which is the desired estimate.
\end{proof}

\begin{lemma}[$W^{1,2}$ controls $W^{1,\infty}$]\label{energycontrolsWoneinfty}
Let $J$ be an almost complex structure on $B^{2n}(1)\subseteq\mathbb R^{2n}$; there exist $\epsilon>0$ and $c<\infty$, depending only on $\left\|J\right\|_{C^2}$ (measured with respect to $g_\mathrm{std}$) with the following property.  Let $u:[0,1]\times[0,1]\to B^{2n}(1)$ be $J$-holomorphic, and suppose that:
\begin{equation}
\int_{[0,1]^2}\biggl[\Bigl|\frac{du}{dx}\Bigr|^2+\Bigl|\frac{du}{dy}\Bigr|^2\biggr]\,dx\,dy<\epsilon
\end{equation}
Then we have:
\begin{equation}
\Bigl|\frac{du}{dx}({\textstyle\frac 12},{\textstyle\frac 12})\Bigr|+\Bigl|\frac{du}{dy}({\textstyle\frac 12},{\textstyle\frac 12})\Bigr|\leq c\cdot\left(\int_{[0,1]^2}\biggl[\Bigl|\frac{du}{dx}\Bigr|^2+\Bigl|\frac{du}{dy}\Bigr|^2\biggr]\,dx\,dy\right)^{1/2}
\end{equation}
\end{lemma}

\begin{proof}
This proof is essentially lifted from McDuff--Salamon \cite[p80, Lemma 4.3.1]{mcduffsalamonJholsymp}.

Let $w:=\frac 12u_x^2+\frac 12u_y^2$ (using the standard inner product $g_\mathrm{std}$), so $w:[0,1]^2\to\mathbb R_{\geq 0}$.  Now we calculate:
\begin{equation}\label{formulaforDeltaw}
w_{xx}+w_{yy}=\Bigl[u_{xx}^2+2u_{xy}^2+u_{yy}^2\Bigr]+\Bigl[u_x\cdot(u_{xxx}+u_{xyy})+u_y\cdot(u_{xxy}+u_{yyy})\Bigr]
\end{equation}

ga^{0,1}_{\tilde C_\alpha,j_y}\otimes_\mathbb C u^\ast TM_{J(\ell_{\alpha,w}(A_y(\cdot)))})$, namely the space of sections $\eta:\tilde C_\alpha\to\Omega^{0,1}_{\tilde C_\alpha,j_y}\otimes_\mathbb C u^\ast TM_{J(\ell_{\alpha,w}(A_y(\cdot)))}$ which are locally of class $W^{k-1,2}$ and which satisfy:
\begin{equation}\label{deltaweightedendII}
\int_{S^1\times[N',\infty)}\sum_{j=0}^{k-1}\Bigl|D^j\bigl[\mathsf{PT}_{u(t,s)\to\gamma_i(t)}\eta(t,s)\bigr]\Bigr|^2e^{2s\delta}\;dt\,ds<\infty
\end{equation}
over positive main ends (along with the analogous condition over negative main ends); this definition is independent of the choice of metric and connection used in \eqref{deltaweightedendII}.

It is well-known (see Proposition \ref{neckestimateHF} below) that for every non-degenerate periodic orbit $\gamma$ of a smooth Hamiltonian $H:M\times S^1\to\mathbb R$ and every smooth $\omega$-compatible almost complex structure $J$ on $M$, there exists $\delta_{H,J,\gamma}>0$ such that for every $u:S^1\times[0,\infty)\to M$ (resp.\ $u:S^1\times(-\infty,0]\to M$) of finite energy satisfying $(du+2dt\otimes X_H)^{0,1}_J=0$ and asymptotic to $u(t,\infty)=\gamma(t)$ (resp.\ $u(t,-\infty)=\gamma(t)$), all derivatives of $u$ decay like $e^{-\delta s}$ for any $\delta<\delta_{H,J,\gamma}$ (precisely, $\delta_{H,J,\gamma}$ is the smallest magnitude of any eigenvalue of the asymptotic linearized operator, which depends only on $\omega$, $H$, $J$, and $\gamma$).  In particular, for $0\leq i\leq k$, there is a corresponding $\delta_i:=\delta_{H(v_i),J(v_i),\gamma_i}>0$.  We fix $\delta\in(0,1)$ with $\delta<\delta_i$ for all $i$; thus $u_1\in W^{k,2,\delta}(C_\alpha,M)$.

Now since $k\geq 6$, there are unique continuous functions:
\begin{equation}\label{intersectionsfunctionHF}
x^i:W^{k,2,\delta}(C_\alpha,M)\to C_\alpha\quad(1\leq i\leq r)
\end{equation}

The remainder of this appendix is devoted to the construction of a germ of a local chart:
\begin{equation}\label{HFgluinggoal}
\Bigl(\mathbb C^d\times(\mathbb R_{\geq 0}^{k-1})^{\leq\mathfrak s}\times\mathbb R^\ast\times\prod_{i=1}^{k\prime}(H^i)^{\leq\mathfrak s}\times K,(0,0,0,0)\Bigr)\to\Bigl(\overline{\mathcal M}(M),(0,0,0,u_0,e_0,\{x_0^i\}_{1\leq i\leq r})\Bigr)
\end{equation}
which respects the natural projection from both sides to $\mathbb C^d\times(\mathbb R_{\geq 0}^{k-1})^{\leq\mathfrak s}\times\mathbb R^\ast\times\prod_{i=1}^{k\prime}(H^i)^{\leq\mathfrak s}\times E/E'$ and whose image is contained in $\overline{\mathcal M}(M)^\mathrm{reg}$ ($K$ denotes the kernel of the linearization of \eqref{finalHFdelbareqn} at the distinguished basepoint of $\overline{\mathcal M}(M)$; see \eqref{definitionofkernel}).  We will also discuss the compatibility of gluing with orientations, and more generally we will discuss how to define coherent orientations on the moduli spaces of Floer trajectories.  Propositions \ref{HFgluingneeded} and \ref{HFgluingSS} follow from the existence of such a chart \eqref{HFgluinggoal} and our earlier observations relating $\overline{\mathcal M}(M)$ to $\overline{\mathcal M}(\sigma,\gamma^-,\gamma^+)_I^{\leq\mathfrak s}$.

\subsection{Pregluing}

Let $\exp:TM\to M$ denote the exponential map of some Riemannian metric on $M$ for which $D$ and $H$ are totally geodesic (such a metric exists since $D$ and $H$ are disjoint).  Recall that $J$ is a smooth family of almost complex structures on $M$ parameterized by $\Delta^n$ which is constant near the vertices.  Let $\nabla$ denote a smooth family of $J$-linear connections on $M$ parameterized by $\Delta^n$ which is constant near the vertices (for instance, we could take $\nabla_XY:=\frac 12(\nabla^0_XY-J(\nabla^0_X(JY)))$ for any fixed connection $\nabla^0$).  Let $\mathsf{PT}_{x\to y}:T_xM\to T_yM$ denote parallel transport via $\nabla$ along the shortest geodesic between $x$ and $y$ (we will only use this notation when it may be assumed that $x$ and $y$ are very close in $M$); note that $\mathsf{PT}_{x\to y}$ is $J$-linear, and that $\mathsf{PT}_{x\to y}$ is a \emph{family} of maps parameterized by $\Delta^n$.

Fix a smooth function $\chi:\mathbb R\to[0,1]$ satisfying:
\begin{equation}
\chi(x)=\begin{cases}0&x\leq 0\cr 1&x\geq 1\end{cases}
\end{equation}

Over a bubble end $S^1\times[0,\infty)$, we define $u_{0|\alpha}$ as follows:
\begin{equation}
u_{0|\alpha}(t,s):=\begin{cases}
u_0(t,s)&s\leq S-1\cr
\exp_{u_0(n)}\left[\chi(S-s)\cdot\exp_{u_0(n)}^{-1}u_0(t,s)\right]&S-1\leq s\leq S\cr
u_0(n)&S\leq s
\end{cases}
\end{equation}

Over a positive main end $S^1\times[N,\infty)$, we define $u_{0|\alpha}$ as:
\begin{equation}
u_{0|\alpha}(t,s):=\begin{cases}
u_0(t,s)&s\leq S-1\cr
\exp_{\gamma(t)}\left[\chi(S-s)\cdot\exp_{\gamma(t)}^{-1}u_0(t,s)\right]&S-1\leq s\leq S\cr
\gamma(t)&S\leq s
\end{cases}
\end{equation}

Over a bubble neck $S^1\times[0,6S]$, we define $u_\alpha$ as:
\begin{equation}
u_\alpha(t,s):=\begin{cases}
u_0(t,s)&s\leq S-1\cr
\exp_{u_0(n)}\left[\chi(S-s)\cdot\exp_{u_0(n)}^{-1}u_0(t,s)\right]&S-1\leq s\leq S\cr
u_0(n)&S\leq s\leq 5S\cr
\exp_{u_0(n)}\left[\chi(S-s')\cdot\exp_{u_0(n)}^{-1}u_0(t',s')\right]&5S\leq s\leq 5S+1\cr
u_0(t',s')&5S+1\leq s
\end{cases}
\end{equation}

and over a main neck $S^1\times[N,6S-N]$, we define $u_\alpha$ as:
\begin{equation}
u_\alpha(t,s):=\begin{cases}
u_0(t,s)&s\leq S-1\cr
\exp_{\gamma(t)}\left[\chi(S-s)\cdot\exp_{\gamma(t)}^{-1}u_0(t,s)\right]&S-1\leq s\leq S\cr
\gamma(t)&S\leq s\leq 5S\cr
\exp_{\gamma(t)}\left[\chi(S+s')\cdot\exp_{\gamma(t)}^{-1}u_0(t',s')\right]&5S\leq s\leq 5S+1\cr
u_0(t',s')&5S+1\leq s
\end{cases}
\end{equation}

Now we observe that $\mathcal F_{\alpha,w,y}$ induces a continuous map:
\begin{equation}
\mathcal F_{\alpha,w,y}:W^{k,2,\delta,\delta}(C_\alpha,u_\alpha^\ast TM)_{D,H}\oplus E\to W^{k-1,2,\delta,\delta}(\tilde C_\alpha,\Omega^{0,1}_{\tilde C_\alpha,j_y}\otimes_\mathbb C u_\alpha^\ast TM_{J(\ell_{\alpha,w}(A_y(\cdot)))})
\end{equation}
which is defined for $\left\|\xi\right\|_{k,2,\delta,\delta}\leq c'$ (some $c'>0$) and small $\alpha,w$.  Moreover, this map is of class $C^{k-2}$.  We denote by:
\begin{equation}
D_{\alpha,w,y}:W^{k,2,\delta,\delta}(C_\alpha,u_\alpha^\ast TM)_{D,H}\oplus E\to W^{k-1,2,\delta,\delta}(\tilde C_\alpha,\Omega^{0,1}_{\tilde C_\alpha,j_y}\otimes_\mathbb C u_\alpha^\ast TM_{J(\ell_{\alpha,w}(A_y(\cdot)))})
\end{equation}
the derivative of $\mathcal F_{\alpha,w,y}$ at zero.

Let $T_\nabla(X,Y):=\nabla_XY-\nabla_YX-[X,Y]$ denote the torsion of $\nabla$.

\begin{lemma}\label{linearizedformulaHF}
The linearized operator $D_{\alpha,w,y}$ is given by:
\begin{align}\label{formulaforlinearizedoperatorHF}
D_{\alpha,w,y}\xi&=\biggl(\nabla^{\ell_{\alpha,w}(A_y(\cdot))}\xi+T_\nabla^{\ell_{\alpha,w}(A_y(\cdot))}(\xi,du_\alpha)\\
&\quad\quad+2d(\operatorname{proj}_{S^1}A_y)\otimes\nabla_\xi^{\ell_{\alpha,w}(A_y(\cdot))}X_{H((\ell_{\alpha,w}\times\operatorname{id}_{S^1})(A_y(\cdot)))}\\
\label{firstLterm}&\quad\quad+\sum_{i=1}^r\frac{d[\lambda(e_0)]}{dx^i}(\alpha,y,x^1,\ldots,x^r,\cdot,u_\alpha(\cdot))(-\operatorname{proj}_{TC_\alpha}\xi(x^i))\\
&\quad\quad+\nabla_\xi^{\ell_{\alpha,w}(A_y(\cdot))}[\lambda(e_0)](\alpha,y,x^1,\ldots,x^r,\cdot,u_\alpha(\cdot))\\
\label{lastLterm}&\quad\quad+\lambda(\operatorname{proj}_E\xi)(\alpha,y,x^1,\ldots,x^r,\cdot,u_\alpha(\cdot))\biggr)^{0,1}_{j_y,J(\ell_{\alpha,w}(A_y(\cdot)))}
\end{align}

We denote the kernel of $D_{0,0,0}$ by:
\begin{equation}\label{definitionofkernel}
K:=\ker D_{0,0,0}\subseteq C^\infty(C_0,u_0^\ast TM)_{D,H}\oplus E
\end{equation}

Over a bubble neck $S^1\times[0,6S]$, we define $\kappa_\alpha$ as:
\begin{equation}\label{kernelpregluingformulaHFbubble}
\kappa_\alpha(t,s):=\begin{cases}
\kappa(t,s)&s\leq S-1\cr
\mathsf{PT}_{u_0(t,s)\to u_\alpha(t,s)}\left[\kappa(t,s)\right]&S-1\leq s\leq S\cr
\mathsf{PT}_{u_0(t,s)\to u_\alpha(t,s)}\left[\kappa(t,s)\right]\cdot(1-\chi(s-S))+\chi(s-S)\cdot \kappa(n)&S\leq s\leq S+1\cr
\kappa(n)&S+1\leq s\leq 5S-1\cr
\mathsf{PT}_{u_0(t',s')\to u_\alpha(t',s')}\left[\kappa(t',s')\right]\cdot(1-\chi(s'-S))+\chi(s'-S)\cdot \kappa(n)&5S-1\leq s\leq 5S\cr
\mathsf{PT}_{u_0(t',s')\to u_\alpha(t',s')}\left[\kappa(t',s')\right]&5S\leq s\leq 5S+1\cr
\kappa(t',s')&5S+1\leq s
\end{cases}
\end{equation}

and over a main neck $S^1\times[N,6S-N]$, we define $\kappa_\alpha$ as:
\begin{equation}\label{kernelpregluingformulaHFmain}
\kappa_\alpha(t,s):=\begin{cases}
\kappa(t,s)&s\leq S-1\cr
\mathsf{PT}_{u_0(t,s)\to u_\alpha(t,s)}\left[\kappa(t,s)\right]&S-1\leq s\leq S\cr
\mathsf{PT}_{u_0(t,s)\to u_\alpha(t,s)}\left[\kappa(t,s)\right]\cdot(1-\chi(s-S))&S\leq s\leq S+1\cr
0&S+1\leq s\leq 5S-1\cr
\mathsf{PT}_{u_0(t',s')\to u_\alpha(t',s')}\left[\kappa(t',s')\right]\cdot(1-\chi(-s'-S))&5S-1\leq s\leq 5S\cr
\mathsf{PT}_{u_0(t',s')\to u_\alpha(t',s')}\left[\kappa(t',s')\right]&5S\leq s\leq 5S+1\cr
\kappa(t',s')&5S+1\leq s
\end{cases}
\end{equation}

We define the map:
\begin{equation}
W^{k-1,2,\delta,\delta}(\tilde C_\alpha,\Omega^{0,1}_{\tilde C_\alpha,j_y}\otimes_\mathbb C u_\alpha^\ast TM_{J(\ell_{\alpha,w}(A_y(\cdot)))})\xrightarrow{\mathrm{break}}W^{k-1,2,\delta,\delta}(\tilde C_0,\Omega^{0,1}_{\tilde C_0,j_y}\otimes_\mathbb C u_{0|\alpha}^\ast TM_{J(\ell_{0,0}(A_y(\cdot)))})
\end{equation}
as follows.  Fix a smooth function $\bar\chi:\mathbb R\to[0,1]$ such that:
\begin{equation}
\bar\chi(x)=\begin{cases}1&x\leq-1\cr0&x\geq+1\end{cases}\qquad\bar\chi(x)+\bar\chi(-x)=1
\end{equation}
Let $\eta\in W^{k-1,2,\delta,\delta}(\tilde C_\alpha,\Omega^{0,1}_{\tilde C_\alpha,j_y}\otimes_\mathbb C u_\alpha^\ast TM_{J(\ell_{\alpha,w}(A_y(\cdot)))})$.  Away from the ends with $\alpha\ne 0$, $\operatorname{break}(\eta)$ is given by $(\operatorname{id}^{1,0})^{-1}(\eta)$, where $\operatorname{id}^{1,0}:TM_{J(\ell_{0,0}(A_y(\cdot)))}\to TM_{J(\ell_{\alpha,w}(A_y(\cdot)))}$ denotes the $(1,0)$-component of the identity map.  In any particular bubble end $[0,\infty)\times S^1\subseteq C_0$ with $\alpha\ne 0$, we define:
\begin{equation}
\operatorname{break}(\eta)(t,s):=\begin{cases}
(\operatorname{id}^{1,0})^{-1}(\eta(t,s))&s\leq 3S-1\cr
\bar\chi(s-3S)\cdot(\operatorname{id}^{1,0})^{-1}(\eta(t,s))&3S-1\leq s\leq 3S+1\cr
0&3S+1\leq s
\end{cases}
\end{equation}

Now suppose that $D_{0|\alpha,0,y}\xi=\operatorname{break}(\eta)$; we must show that:
\begin{equation}
\left\|D_{\alpha,w,y}(\operatorname{glue}(\xi))-\eta\right\|_{k-1,2,\delta,\delta}\leq c\cdot\bigl(\left|\alpha\right|^\epsilon+\left|w\right|\bigr)\left\|\xi\right\|_{k,2,\delta,\delta}
\end{equation}
Using the triangle inequality and the fact that $\eta=\operatorname{glue}(\operatorname{break}'(\eta))=\operatorname{glue}(\operatorname{id}^{1,0}(D_{0|\alpha,0,y}\xi))$, we conclude that $\left\|D_{\alpha,w,y}(\operatorname{glue}(\xi))-\eta\right\|$ is bounded above by:
\begin{equation*}
\left\|D_{\alpha,w,y}(\operatorname{glue}(\xi))-\operatorname{glue}(D_{\alpha,w,y}(\xi))\right\|+\left\|\operatorname{glue}\left[D_{\alpha,w,y}(\xi)-\operatorname{id}^{1,0}(D_{0|\alpha,0,y}(\xi))\right]\right\|
\end{equation*}
We now estimate each term separately.

To estimate $\left\|D_{\alpha,w,y}(\operatorname{glue}(\xi))-\operatorname{glue}(D_{\alpha,w,y}(\xi))\right\|$, argue as follows.  The difference is only nonzero over the regions $S^1\times([2S,2S+1]\cup[4S-1,4S])$ of each neck.  Now the norm is bounded by $\left\|\xi\right\|e^{-2S\delta}$ (calculation left to the reader), where the factor of $e^{-2S\delta}$ comes as the ratio of the weight given to $S^1\times[4S-1,4S]$ inside a neck vs inside an end; this gives the desired bound since $\delta>0$.

To estimate $\left\|\operatorname{glue}\left[D_{\alpha,w,y}(\xi)-\operatorname{id}^{1,0}(D_{0|\alpha,0,y}\xi)\right]\right\|$, argue as follows.  This is bounded by a constant times the $(k-1,2,\delta,\delta)$-norm of $D_{\alpha,w,y}(\xi)-\operatorname{id}^{1,0}(D_{0|\alpha,0,y}\xi)$ over the complement of the subsets $S^1\times[4S,\infty)$ of the ends.  Now this is bounded by $(\left|\alpha\right|^\epsilon+\left|w\right|)\left\|\xi\right\|_{k,2,\delta,\delta}$ using the reasoning from Lemma \ref{approxmiddleHF}.
\end{proof}

\begin{proposition}[Approximate right inverse $T_{\alpha,w,y}$]\label{approxworksHF}
We have:
\begin{align}
\left\|T_{\alpha,w,y}\right\|&\leq c\\
\label{TapproxeqnHF}\left\|D_{\alpha,w,y} T_{\alpha,w,y}-\mathbf 1\right\|&\to 0\\
\operatorname{im} T_{\alpha,w,y}&\subseteq\ker L_\alpha
\end{align}
as $(\alpha,w,y)\to 0$, for $c<\infty$ depending on data which has been previously fixed.
\end{proposition}

\begin{proof}
It is easy to see that all the maps in \eqref{biginversediagramHF} are uniformly bounded.  Hence $\left\|T_{\alpha,w,y}\right\|\leq c$ as $(\alpha,w,y)\to 0$.  Now Lemma \ref{bootstrappingapprox} combined with Lemmas \ref{approxbottomHF}, \ref{approxmiddleHF}, \ref{approxtopHF} show that for $(\alpha,w,y)\to 0$, we have $\left\|D_{\alpha,w,y} T_{\alpha,w,y}-\mathbf 1\right\|\to 0$.  We observed earlier that $\operatorname{im} T_{\alpha,w,y}\subseteq\ker L_\alpha$.
\end{proof}

\begin{definition}[Right inverse $Q_{\alpha,w,y}$]
We define a map:
\begin{equation}
Q_{\alpha,w,y}:W^{k-1,2,\delta,\delta}(\tilde C_\alpha,\Omega^{0,1}_{\tilde C_\alpha,j_y}\otimes_\mathbb C u_\alpha^\ast TM_{J(\ell_{\alpha,w}(A_y(\cdot)))})\to W^{k,2,\delta,\delta}(C_\alpha,u_\alpha^\ast TM)_{D,H}\oplus E
\end{equation}
as the sum:
\begin{equation}
Q_{\alpha,w,y}:=T_{\alpha,w,y}\sum_{k=0}^\infty(\mathbf 1-D_{\alpha,w,y}T_{\alpha,w,y})^k
\end{equation}

We have:
\begin{align}
\left\|Q_{\alpha,w,y}\right\|&\leq c\\
D_{\alpha,w,y}Q_{\alpha,w,y}&=\mathbf 1\\
\operatorname{im} Q_{\alpha,w,y}&\subseteq\ker L_\alpha
\end{align}
uniformly over $(\alpha,w,y)$ in a neighborhood of zero, for $c<\infty$ depending on data which has been previously fixed.
\end{proposition}

\begin{proof}
Apply Lemma \ref{bootstrapinverse} and Proposition \ref{approxworksHF}.
\end{proof}

\subsection{Quadratic estimates}

\begin{proposition}[Quadratic estimate]\label{quadestimateHF}
There exist $c'>0$ and $c<\infty$ (depending on data which has been previously fixed) such that for $\left\|\xi_1\right\|_{k,2,\delta,\delta},\left\|\xi_2\right\|_{k,2,\delta,\delta}\leq c'$, we have:
\begin{equation}\label{quadestgoalHF}
\bigl\|D_{\alpha,w,y}(\xi_1-\xi_2)-(\mathcal F_{\alpha,w,y}\xi_1-\mathcal F_{\alpha,w,y}\xi_2)\bigr\|_{k-1,2,\delta,\delta}\leq c\cdot\left\|\xi_1-\xi_2\right\|_{k,2,\delta,\delta}(\left\|\xi_1\right\|_{k,2,\delta,\delta}+\left\|\xi_2\right\|_{k,2,\delta,\delta})
\end{equation}
(and $\mathcal F_{\alpha,w,y}\xi_1$ and $\mathcal F_{\alpha,w,y}\xi_2$ are both defined), uniformly over $(\alpha,w,y)$ in a neighborhood of zero.
\end{proposition}

\begin{proof}
The proof is identical to the proof of Lemma \ref{quadestimate}, with the evident notational differences, $\mathcal F_{\alpha,w,y}$ for $\mathcal F_{\alpha,y}$, and Lemma \ref{linearizedformulaHF} for Lemma \ref{linearizedformula}.  As with Lemma \ref{quadestimate}, we actually prove the stronger statement that:
\begin{equation}\label{derivislipHF}
\left\|\mathcal F_{\alpha,w,y}'(0,\xi)-\mathcal F_{\alpha,w,y}'(\zeta,\xi)\right\|_{k-1,2,\delta,\delta}\leq c\cdot\left\|\zeta\right\|_{k,2,\delta,\delta}\left\|\xi\right\|_{k,2,\delta,\delta}
\end{equation}
\end{proof}

\subsection{Newton--Picard iteration}

\begin{lemma}\label{contractionpropHF}
There exists $c'>0$ (depending on data which has been previously fixed) such that for sufficiently small $(\alpha,w,y)$:
\begin{rlist}
\item The map $\mathcal F_{\alpha,w,y}$ is defined for $\left\|\xi\right\|_{k,2,\delta,\delta}\leq c'$.
\item For $\xi_1-\xi_2\in\operatorname{im} Q_{\alpha,w,y}$ and $\left\|\xi_1\right\|_{k,2,\delta,\delta},\left\|\xi_2\right\|_{k,2,\delta,\delta}\leq c'$, we have:
\begin{equation}
\left\|(\xi_1-\xi_2)-(Q_{\alpha,w,y}\mathcal F_{\alpha,w,y}\xi_1-Q_{\alpha,w,y}\mathcal F_{\alpha,w,y}\xi_2)\right\|_{k,2,\delta,\delta}\leq\frac 12\left\|\xi_1-\xi_2\right\|_{k,2,\delta,\delta}
\end{equation}
\end{rlist}
\end{lemma}

\begin{proof}
The proof is identical to the proof of Lemma \ref{contractionprop}, using Proposition \ref{quadestimateHF} in place of Proposition \ref{quadestimate}.
\end{proof}

\begin{proposition}[Newton--Picard iteration]\label{newtoniterationHF}
There exists $c'>0$ (depending on data which has been previously fixed) so that for $(\alpha,w,y,\kappa\in K)$ sufficiently small, there exists a unique $\kappa_{\alpha,w,y}\in W^{k,2,\delta,\delta}(C_\alpha,u_\alpha^\ast TM)_{D,H}\oplus E$ satisfying:
\begin{align}
\kappa_{\alpha,w,y}&\in\kappa_\alpha+\operatorname{im} Q_{\alpha,w,y}\\
\left\|\kappa_{\alpha,w,y}\right\|_{k,2,\delta,\delta}&\leq c'\\
\mathcal F_{\alpha,w,y}\kappa_{\alpha,w,y}&=0
\end{align}
\end{proposition}

\begin{proof}
The proof is essentially identical to the proof of Proposition \ref{newtoniteration}; we write it out anyway.

In fact, we will show that $\kappa_{\alpha,w,y}$ is given explicitly as the limit of the Newton iteration:
\begin{align}
\xi_0&:=\kappa_\alpha\\
\xi_n&:=\xi_{n-1}-Q_{\alpha,w,y}\mathcal F_{\alpha,w,y}\xi_{n-1}
\end{align}

By Lemma \ref{contractionpropHF}, the map $\xi\mapsto\xi-Q_{\alpha,w,y}\mathcal F_{\alpha,w,y}\xi$ is a $\frac 12$-contraction mapping when restricted to:
\begin{equation}\label{domainofcontractionHF}
\{\xi\in\kappa_\alpha+\operatorname{im} Q_{\alpha,w,y}:\left\|\xi\right\|_{k,2,\delta,\delta}\leq c'\}
\end{equation}
To finish the proof, it suffices to show that (for sufficiently small $(\alpha,w,y,\kappa)$) \eqref{domainofcontractionHF} is nonempty and is mapped to itself by $\xi\mapsto\xi-Q_{\alpha,w,y}\mathcal F_{\alpha,w,y}\xi$.

We know that $\left\|\kappa_\alpha\right\|_{k,2,\delta,\delta}\to 0$ as $\kappa\to 0$ (uniformly in $(\alpha,w,y)$), so \eqref{domainofcontractionHF} is nonempty.  By using Proposition \ref{quadestimateHF} with $(\xi_1,\xi_2)=(0,\kappa_\alpha)$ and Lemmas \ref{mappregluingissmallHF} and \ref{pregluingKestimateHF}, we conclude that:
\begin{equation}\label{kernelclosetoholomorphicHF}
\left\|\mathcal F_{\alpha,w,y}\kappa_\alpha\right\|_{k-1,2,\delta,\delta}\to 0
\end{equation}
as $(\alpha,w,y,\kappa)\to 0$.  Since the operator norm of $Q_{\alpha,w,y}$ is bounded uniformly as $(\alpha,w,y)\to 0$, we see that $\kappa_\alpha$ is almost fixed by $\xi\mapsto\xi-Q_{\alpha,w,y}\mathcal F_{\alpha,w,y}\xi$ as $(\alpha,w,y,\kappa)\to 0$.  It then follows from the contraction property that $\xi\mapsto\xi-Q_{\alpha,w,y}\mathcal F_{\alpha,w,y}\xi$ maps \eqref{domainofcontractionHF} to itself.
\end{proof}

\subsection{Gluing}

\begin{definition}[Gluing map]
We define:
\begin{align}
u_{\alpha,w,y,\kappa}&:=\exp_{u_\alpha}\kappa_{\alpha,w,y}\\
e_{\alpha,w,y,\kappa}&:=e_0+\operatorname{proj}_E\kappa_{\alpha,w,y}
\end{align}

where $f_i:[0,6S_i]\to[0,6S]$ is smooth and satisfies:
\begin{align}
f_i(s):=&\begin{cases}
s&s\leq S-2\cr
s-3S_i+3S&3S_i-2S+2\leq s\leq 3S_i+2S-2\cr
s-6S_i+6S&6S_i-S+2\leq s\cr
\end{cases}\\
f_i([S-2,3S_i-2S+2])&\subseteq[S-2,S+2]\\
f_i([3S_i+2S-2,6S_i-S+2])&\subseteq[5S-2,5S+2]
\end{align}

Then:
\begin{equation*}
\left|D^k\xi\right|\leq c_k\cdot\left[e^{-\mu\delta s}\left(\int_{S^1}\bigl|\xi(t,0)\bigr|^2\,dt\right)^{1/2}+e^{-\mu\delta(N-s)}\left(\int_{S^1}\bigl|\xi(t,N)\bigr|^2\,dt\right)^{1/2}\right]\qquad 1\leq s\leq N-1
\end{equation*}
for all $k\geq 0$.
\end{proposition}

\begin{proof}
This proof is adapted from Salamon \cite[p170, Lemma 2.11]{salamonnotes}.

We have by assumption that $\partial_su+J(u)(\partial_tu-X_H(u))=0$, where $u(t,s)=\exp_{\gamma(t)}\xi(t,s)$.  Now we may rewrite this equation in exponential coordinates in terms of $\xi$ as follows.  Denote by $\partial_t$ the connection $\mathcal L_{X_H}$ on $\gamma^\ast TM$, which is given by the Lie derivative with respect to $X_H$.  Now the equation for $u$ is equivalent to:
\begin{equation}
\partial_s\xi+J\partial_t\xi+A(\xi)\partial_t\xi+Q(\xi)=0
\end{equation}
for certain smooth (non-linear) bundle maps $A:\gamma^\ast TM\to\operatorname{End}(\gamma^\ast TM)$ and $Q:\gamma^\ast TM\to\gamma^\ast TM$.  We have $A(0)=0$, $Q(0)=0$, and $Q'(0,\cdot)=0$ (we denote by $A'$ and $Q'$ their ``vertical'' derivatives).

Now we let:
\begin{equation}
f(s):=\int_{S^1}\left|\xi(t,s)\right|^2dt=\left\|\xi\right\|_2^2
\end{equation}

Now let us observe that there are natural (odd) ``boundary'' maps:
\begin{align}
\label{simplexflowproductor}\mathfrak o_\sigma&\to\mathfrak o_{\sigma|[0\ldots k]}\otimes\mathfrak o_{\sigma|[k\ldots n]}\\
\label{simplexflowfaceor}\mathfrak o_\sigma&\to\mathfrak o_{\sigma|[0\ldots\hat k\ldots n]}
\end{align}
induced by the geometric inclusions of boundary strata \eqref{Fproduct}--\eqref{Fface}.  Specifically, the first map is induced by the inclusion of the space of pairs of flow lines on $\sigma|[0\ldots k]$ and $\sigma|[k\ldots n]$ into the space of flow lines on $\sigma$ ($0<k<n$), and the second by the inclusion of flow lines on $\sigma|[0\ldots\hat k\ldots n]$ into flow lines on $\sigma$ ($0<k<n$).  In fact, the first map \eqref{simplexflowproductor} admits the following alternative description, which shows that it is in fact defined for $0\leq k\leq n$.  Let $\mathcal F^{(i)}(\sigma)$ denote the moduli space of stable broken Morse flow lines on a simplex $\sigma$ with $i$ ordered marked points appearing in order (this is defined in the expected way, allowing constant flow lines as long as they are stabilized by the presence of at least one marked point).  Denote the orientation module of $\mathcal F^{(i)}(\sigma)$ by $\mathfrak o_\sigma^{(i)}$, and note that there is a natural isomorphism $\mathfrak o_\sigma^{(i)}=\mathfrak o_\sigma\otimes\mathfrak o_\mathbb R^{\otimes i}$ (even for $\dim\sigma=0$; this provides another justification of our definition of $\mathfrak o_\sigma$ in this case).  Now there is a natural concatenation map $\mathcal F^{(i)}(\sigma|[0\ldots k])\times\mathcal F^{(j)}(\sigma|[k\ldots n])\to\mathcal F^{(i+j)}(\sigma)$ which is the inclusion of a codimension one boundary stratum, thus giving rise to a boundary map $\mathfrak o_\sigma^{(i+j)}\to\mathfrak o_{\sigma|[0\ldots k]}^{(i)}\otimes\mathfrak o_{\sigma|[k\ldots n]}^{(j)}$.  After factoring out $\mathfrak o_\mathbb R^{\otimes(i+j)}$, this map coincides with \eqref{simplexflowproductor} for $0<k<n$, and thus may be used to define \eqref{simplexflowproductor} for $0\leq k\leq n$.

\begin{remark}
The standard orientation of $\mathbb R$ gives a standard generator $[\mathbb R]_1\otimes\cdots\otimes[\mathbb R]_{n-1}\in\mathfrak o_\sigma$ for $\dim\sigma>0$, and $[\mathbb R]^\vee\in\mathfrak o_\sigma$ for $\dim\sigma=0$, where $[\mathbb R]\cdot[\mathbb R]^\vee=1$ (i.e.\ $[\mathbb R]^\vee\in\mathfrak o_\mathbb R^\vee$ is the ``right dual'' of $[\mathbb R]\in\mathfrak o_\mathbb R$).  Using these generators to trivialize $\mathfrak o_\sigma$ determines a sign convention in which \eqref{simplexflowproductor} is given by $(-1)^{k+1}$ and \eqref{simplexflowfaceor} is given by $(-1)^k$.
\end{remark}

\subsubsection{Orientations of linearized operators of Floer equations}

Fix two Hamiltonians $H_0,H_1:M\times S^1\to\mathbb R$ and two non-degenerate periodic orbits $p,q:S^1\to M$ of $H_0,H_1$ respectively.  Now for any path of $\omega$-compatible almost complex structures $J:\mathbb R\to J(M)$ (constant near $s=\pm\infty$), any path of Hamiltonians $H:M\times S^1\times\mathbb R\to\mathbb R$ (constant near $s=\pm\infty$) with $H(s=-\infty)=H_0$ and $H(s=\infty)=H_1$, and any map $u:S^1\times\mathbb R\to M$ in $W^{k,2,\delta}(S^1\times\mathbb R,M)$ (converging to $q$ at $-\infty$ and to $p$ at $\infty$), there is a natural linearized operator:
\begin{equation}\label{Dfloer}
D_\text{Floer}:W^{k,2,\delta}(S^1\times\mathbb R,u^\ast TM)\to W^{k-1,2,\delta}(S^1\times\mathbb R,\Omega^{0,1}_{S^1\times\mathbb R}\otimes_\mathbb C u^\ast TM_J)
\end{equation}
(we assume that $\delta>0$ is less than the smallest positive eigenvalues of the asymptotic linearized operators).  Let us agree to define this linearized operator using the $\mathbb R$-family of $J$-linear connections on $TM$ given by $\nabla_XY:=\frac 12(\nabla^0_XY-J(\nabla^0_X(JY)))$, where $\nabla^0$ denotes the Levi-Civita connection of the metric associated to the compatible pair $(\omega,J)$.  The results of Floer--Hofer \cite{floerhoferorientations} (see the remark after Theorem 2) imply that the Fredholm orientation line of $D_\text{Floer}$ is a trivial bundle over the space of paths $H$, $J$, and maps $u$.  Thus if we fix $p$, $q$, and a homotopy class of maps $u$, there is a well-defined orientation line $\mathfrak o_{p,q}$, canonically isomorphic to $\mathfrak o_{D_\text{Floer}}$ for any choice of $H$, $J$, and $u$.

Floer--Hofer \cite[Theorem 10]{floerhoferorientations} also construct natural associative (even) isomorphisms:
\begin{equation}\label{floerhoferoogluing}
\mathfrak o_{p,q}\otimes\mathfrak o_{q,r}\to\mathfrak o_{p,r}
\end{equation}

Moreover, under these identifications, the boundary maps on orientation sheaves induced (as in \eqref{sesofO}) by the structure maps:
\begin{align}
\label{hforproduct}\overline{\mathcal M}(\sigma|[0\ldots k],p,q)\times\overline{\mathcal M}(\sigma|[k\ldots n],q,r)&\to\partial\overline{\mathcal M}(\sigma,p,r)\\
\label{hforface}\overline{\mathcal M}(\sigma|[0\ldots\hat k\ldots n],p,q)&\to\partial\overline{\mathcal M}(\sigma,p,q)
\end{align}
coincide with the maps:
\begin{align}
\label{hforproductor}\mathfrak o_\sigma\otimes\mathfrak o_{p,r}&\to\mathfrak o_{\sigma|[0\ldots k]}\otimes\mathfrak o_{p,q}\otimes\mathfrak o_{\sigma|[k\ldots n]}\otimes\mathfrak o_{q,r}\\
\label{hforfaceor}\mathfrak o_\sigma\otimes\mathfrak o_{p,q}&\to\mathfrak o_{\sigma|[0\ldots\hat k\ldots n]}\otimes\mathfrak o_{p,q}
\end{align}
induced by \eqref{simplexflowproductor}--\eqref{simplexflowfaceor} and \eqref{floerhoferoogluing}.
\end{proposition}

Let us introduce various linearized operators which will play a role in the proof of Proposition \ref{gluingHForientations} below.  At any point in a thickened moduli space $\overline{\mathcal M}(\sigma,p,q)_I$, we have a linearized operator:
\begin{equation}
\label{linearizedstd}D:E_I\oplus W^{k,2,\delta}(C,u^\ast TM)\to W^{k-1,2,\delta}(C,\Omega^{0,1}_C\otimes_\mathbb C u^\ast TM_{J(\ell(\cdot))})
\end{equation}
