\begin{tikzcd}
\tilde Z_\bullet\arrow{r}{\widetilde\mathbb H(\mathcal X)}\arrow{d}[swap]{\pi}&H^0(\mathsf{Ch}_{R[[H]]})\\
Z_\bullet
