\begin{rlist}
\item$\mathcal X(\sigma^1,p,p)=\mathcal X(\sigma^1,p,p)^\mathrm{reg}$ is a single point and $\omega(\sigma^1,p,p)=1$, for all $p$.
\item$\mathcal X(\sigma^0,p,q)=\varnothing\implies\mathcal X(\sigma^i,p,q)=\varnothing$ for all $i$ and $p\ne q$
\end{rlist}
(where $\sigma^i$ denotes the completely degenerate $i$-simplex over $\sigma^0$).  We have:
\begin{equation}
\begin{tikzcd}
\tilde Z_\bullet\arrow{r}{\widetilde\mathbb H(\mathcal X)}\arrow{d}[swap]{\pi}&H^0(\mathsf{Ch}_{R[[H]]})\\
Z_\bullet
\end{tikzcd}
\end{equation}
(abusing notation and use $\widetilde\mathbb H(\mathcal X):\tilde Z_\bullet\to H^0(\mathsf{Ch}_{R[[H]]})$ to denote the composition of $\widetilde\mathbb H(\mathcal X)$ with the forgetful functor $\mathsf{N}_{\mathsf{dg}}\to H^0$).  The hypotheses of Lemma \ref{descentofdiagram} are satisfied by Propositions \ref{trivialKanfibration} and \ref{degenerateID}, and hence we get a canonical descent:
\begin{equation}
\mathbb H(\mathcal X)_{A,\omega}:Z_\bullet\to H^0(\mathsf{Ch}_{R[[H]]})
\end{equation}
We will write $\mathbb H(\mathcal X)$ for $\mathbb H(\mathcal X)_{A,\omega}$ when the atlas and orientations are clear from context.
\end{definition}

